window.GITA=window.GITA||{};GITA.capitulos=GITA.capitulos||{};GITA.capitulos[6]={"numero": 6, "titulo": "El yoga del dominio de sí", "versos": [{"n": 1, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "अनाश्रितः कर्मफलं कार्यं कर्म करोति यः ।", "स संन्यासी च योगी च न निरग्निर्न चाक्रियः ॥१॥"], "iast": ["śrī-bhagavān uvāca", "anāśritaḥ karma-phalaṃ kāryaṃ karma karoti yaḥ", "sa saṃnyāsī ca yogī ca na niragnir na cākriyaḥ"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Quien hace la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a> que debe hacerse sin apoyarse en el <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a> de la acción, ése es <a class=\"t\" href=\"glosario.html#sannyasa\" data-t=\"sannyasa\">renunciante</a> y es <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a>; no el que ha dejado el <a class=\"t\" href=\"glosario.html#agni\" data-t=\"agni\">fuego</a> sagrado, ni el que ha dejado los ritos.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria) + bhagavat (el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "anāśritaḥ", "sa": "अनाश्रितः", "gram": "nom. sg. m. ppp", "es": "sin apoyarse en", "analisis": "an (no) + ā-√śri (apoyarse, depender de)"}, {"iast": "karma-phalam", "sa": "कर्मफलम्", "gram": "ac. sg. n. comp.", "es": "el fruto de la acción", "ref": "phala", "analisis": "karman (acción) + phala (fruto)"}, {"iast": "kāryam", "sa": "कार्यम्", "gram": "ac. sg. n. gerundivo", "es": "que debe hacerse", "analisis": "√kṛ (hacer): «lo que ha de hacerse»"}, {"iast": "karma", "sa": "कर्म", "gram": "ac. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "karoti", "sa": "करोति", "gram": "3 sg. pres. act.", "es": "hace", "analisis": "√kṛ (hacer)"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "saṃnyāsī", "sa": "संन्यासी", "gram": "nom. sg. m.", "es": "renunciante", "ref": "sannyasa", "analisis": "saṃnyāsin: el que practica la renuncia"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "yogui", "ref": "yogin", "analisis": "yogin: el que practica el yoga"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "niragniḥ", "sa": "निरग्निः", "gram": "nom. sg. m. comp.", "es": "el que no tiene fuego", "ref": "agni", "analisis": "nis (sin) + agni (fuego): el que ya no mantiene los fuegos rituales"}, {"iast": "akriyaḥ", "sa": "अक्रियः", "gram": "nom. sg. m. comp.", "es": "el que no tiene ritos", "analisis": "a (sin) + kriyā (acción, rito)"}], "nota": "<p>El capítulo vuelve a la pregunta con que empezaba el anterior: quién es de verdad renunciante (<a class=\"vref\" href=\"capitulo-05.html#v3\" data-v=\"5.3\">5.3</a>). <em>Niragni</em>, «sin fuego», designa al que ya no mantiene los fuegos rituales del hogar, como hace el renunciante al dejar la vida de cabeza de familia; <em>akriya</em>, «sin acciones», al que ha dejado los ritos y las obras. La Gītā no niega que exista esa renuncia exterior: niega que baste. La renuncia que cuenta es interior, y la nombra el verso siguiente.</p>", "interp": [{"titulo": "Un elogio del yoga de la acción", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende que el verso llama «renunciante» y «yogui» al que practica el yoga de la acción en un sentido figurado, para alabarlo: es renunciante porque ha dejado la intención puesta en el fruto, y yogui porque obra al servicio del yoga y ha dejado esa intención, que dispersa la mente. La renuncia en sentido propio, el abandono de todas las acciones y de sus frutos, sigue siendo para él la del monje que ha dejado los fuegos y los ritos.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La renuncia sin hábito", "html": "<p>El verso retoma el hilo de <a class=\"vref\" href=\"capitulo-05.html#v1\" data-v=\"5.1\">5.1</a>–<a class=\"vref\" href=\"capitulo-05.html#v6\" data-v=\"5.6\">5.6</a> y lo resume en una fórmula: lo que define al renunciante no son los signos exteriores —apagar los fuegos del hogar, abandonar los ritos—, sino el no depender del fruto. Es la misma distinción que el capítulo 18 hará entre renuncia (<em>saṃnyāsa</em>) y abandono (<em>tyāga</em>) (<a class=\"vref\" href=\"capitulo-18.html#v2\" data-v=\"18.2\">18.2</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "renunciar-a-la-intencion"}, {"n": 2, "hablante": "krsna", "sa": ["यं संन्यासमिति प्राहुर्योगं तं विद्धि पाण्डव ।", "न ह्यसंन्यस्तसङ्कल्पो योगी भवति कश्चन ॥२॥"], "iast": ["yaṃ saṃnyāsam iti prāhur yogaṃ taṃ viddhi pāṇḍava", "na hy asaṃnyasta-saṅkalpo yogī bhavati kaścana"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Lo que llaman renuncia, sábelo, oh <a class=\"t\" href=\"glosario.html#pandava\" data-t=\"pandava\">Pāṇḍava</a>, es el yoga; pues nadie llega a ser <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> sin haber renunciado a la <a class=\"t\" href=\"glosario.html#sankalpa\" data-t=\"sankalpa\">intención</a>.</span>", "palabras": [{"iast": "yam", "sa": "यम्", "gram": "ac. sg. m. rel.", "es": "lo que"}, {"iast": "saṃnyāsam", "sa": "संन्यासम्", "gram": "ac. sg. m.", "es": "renuncia", "ref": "sannyasa"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cita)"}, {"iast": "prāhuḥ", "sa": "प्राहुः", "gram": "3 pl. pf. act.", "es": "llaman", "analisis": "pra-√ah (decir, llamar)"}, {"iast": "yogam", "sa": "योगम्", "gram": "ac. sg. m.", "es": "yoga", "ref": "yoga"}, {"iast": "tam", "sa": "तम्", "gram": "ac. sg. m. pron.", "es": "eso"}, {"iast": "viddhi", "sa": "विद्धि", "gram": "2 sg. impv. act.", "es": "sabe", "analisis": "√vid (saber)"}, {"iast": "pāṇḍava", "sa": "पाण्डव", "gram": "voc. sg. m.", "es": "oh Pāṇḍava", "ref": "pandava"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "asaṃnyasta-saṅkalpaḥ", "sa": "असंन्यस्तसङ्कल्पः", "gram": "nom. sg. m. comp.", "es": "sin haber renunciado a la intención", "ref": "sankalpa", "analisis": "a (no) + saṃnyasta (renunciado) + saṅkalpa (intención): bahuvrīhi"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "yogui", "ref": "yogin"}, {"iast": "bhavati", "sa": "भवति", "gram": "3 sg. pres. act.", "es": "llega a ser", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "kaścana", "sa": "कश्चन", "gram": "nom. sg. m. indef.", "es": "nadie (con na)"}], "nota": "<p><em>Saṅkalpa</em> es la intención o el propósito: el movimiento de la mente que se forma una imagen de lo que quiere y se pone a perseguirlo. Renunciar a él no es dejar de actuar, sino dejar de actuar para obtener lo imaginado. Por eso renuncia y yoga coinciden: las dos piden lo mismo, abandonar el deseo del fruto. Véase <a class=\"vref\" href=\"capitulo-04.html#v19\" data-v=\"4.19\">4.19</a>, donde el sabio emprende sus obras «libre del deseo y de la intención», y <a class=\"vref\" href=\"capitulo-06.html#v24\" data-v=\"6.24\">6.24</a>, donde los deseos «nacen de la intención».</p>", "interp": [{"titulo": "La intención que se fija en el fruto", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende el <em>saṅkalpa</em> como la intención de la mente que se fija en los frutos de las acciones. Quien no la ha abandonado no puede ser yogui, porque esa intención es lo que agita la mente; en eso se parecen el yoga de la acción y la renuncia.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "renunciar-a-la-intencion"}, {"n": 3, "hablante": "krsna", "sa": ["आरुरुक्षोर्मुनेर्योगं कर्म कारणमुच्यते ।", "योगारूढस्य तस्यैव शमः कारणमुच्यते ॥३॥"], "iast": ["ārurukṣor muner yogaṃ karma kāraṇam ucyate", "yogārūḍhasya tasyaiva śamaḥ kāraṇam ucyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Para el <a class=\"t\" href=\"glosario.html#muni\" data-t=\"muni\">sabio</a> que quiere ascender al yoga, el medio, se dice, es la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>; para ese mismo, cuando ya <a class=\"t\" href=\"glosario.html#yogarudha\" data-t=\"yogarudha\">ha ascendido al yoga</a>, el medio, se dice, es la calma.</span>", "palabras": [{"iast": "ārurukṣoḥ", "sa": "आरुरुक्षोः", "gram": "gen. sg. m.", "es": "del que quiere ascender", "ref": "yogarudha", "analisis": "desiderativo de ā-√ruh (subir, montar): «que desea subir»"}, {"iast": "muneḥ", "sa": "मुनेः", "gram": "gen. sg. m.", "es": "del sabio", "ref": "muni"}, {"iast": "yogam", "sa": "योगम्", "gram": "ac. sg. m.", "es": "al yoga", "ref": "yoga"}, {"iast": "karma", "sa": "कर्म", "gram": "nom. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "kāraṇam", "sa": "कारणम्", "gram": "nom. sg. n.", "es": "el medio", "analisis": "√kṛ (hacer): «lo que produce», causa, instrumento"}, {"iast": "ucyate", "sa": "उच्यते", "gram": "3 sg. pres. pas.", "es": "se dice", "analisis": "√vac (decir), pasiva"}, {"iast": "yoga-ārūḍhasya", "sa": "योगारूढस्य", "gram": "gen. sg. m. comp.", "es": "del que ha ascendido al yoga", "ref": "yogarudha", "analisis": "yoga + ārūḍha (subido), ppp de ā-√ruh"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. m. pron.", "es": "de ése"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "mismo"}, {"iast": "śamaḥ", "sa": "शमः", "gram": "nom. sg. m.", "es": "la calma", "analisis": "√śam (calmarse, cesar): sosiego, cese"}, {"iast": "kāraṇam", "sa": "कारणम्", "gram": "nom. sg. n.", "es": "el medio"}, {"iast": "ucyate", "sa": "उच्यते", "gram": "3 sg. pres. pas.", "es": "se dice", "analisis": "√vac (decir), pasiva"}], "nota": "<p>La imagen es la de subir (ā-√ruh), como se sube a un caballo, a un carro o a una montaña. <em>Ārurukṣu</em> es «el que desea subir»; <em>yogārūḍha</em>, «el que ya ha subido». El verso no dice que la acción deje de existir arriba, sino que cambia lo que hace avanzar: abajo, la acción sin apego; arriba, la calma. Qué significa exactamente esa calma es una de las cuestiones disputadas del capítulo (véanse las alternativas).</p>", "interp": [{"titulo": "Primero la acción, después la renuncia", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende la «calma» como el apartarse de toda acción: el yoga de la acción es el medio del que aún aspira, porque purifica la mente; cuando ha llegado, el medio es la renuncia a las obras. El verso confirma así su lectura de todo el libro: la acción prepara, pero no es la meta.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Una escalera de dos tramos", "html": "<p>El verso admite dos lecturas, y las dos encuentran apoyo en la Gītā. A favor de las etapas sucesivas está el lenguaje mismo de la subida: lo que sirve para subir no sirve para quedarse arriba. A favor de la calma que acompaña la acción, el ejemplo de los sabios que siguieron actuando, como Janaka (<a class=\"vref\" href=\"capitulo-03.html#v20\" data-v=\"3.20\">3.20</a>), y el retrato del renunciante que actúa en <a class=\"vref\" href=\"capitulo-06.html#v1\" data-v=\"6.1\">6.1</a>.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Para el sabio que quiere ascender al yoga, el medio, se dice, es la acción; para ese mismo, cuando ya ha ascendido al yoga, el medio, se dice, es el cese de la acción.", "nota": "<p><em>Śama</em> es «calma» y también «cese». Si se entiende como el cese de toda acción —así lo leen <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, y también <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, aunque para él las obras sólo cesan una vez alcanzada la visión del sí-mismo—, el verso describe dos etapas sucesivas: primero actuar, después dejar de actuar. Si se entiende como la calma interior, ésta puede acompañar a la acción del que ya ha llegado, como pide el resto del libro (<a class=\"vref\" href=\"capitulo-03.html#v25\" data-v=\"3.25\">3.25</a>, <a class=\"vref\" href=\"capitulo-06.html#v1\" data-v=\"6.1\">6.1</a>).</p>"}], "ens": "ascender-al-yoga"}, {"n": 4, "hablante": "krsna", "sa": ["यदा हि नेन्द्रियार्थेषु न कर्मस्वनुषज्जते ।", "सर्वसङ्कल्पसंन्यासी योगारूढस्तदोच्यते ॥४॥"], "iast": ["yadā hi nendriyārtheṣu na karmasv anuṣajjate", "sarva-saṅkalpa-saṃnyāsī yogārūḍhas tadocyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Cuando ya no se apega a los <a class=\"t\" href=\"glosario.html#visaya\" data-t=\"visaya\">objetos de los sentidos</a> ni a las <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a>, y ha renunciado a toda <a class=\"t\" href=\"glosario.html#sankalpa\" data-t=\"sankalpa\">intención</a>, entonces se dice que <a class=\"t\" href=\"glosario.html#yogarudha\" data-t=\"yogarudha\">ha ascendido al yoga</a>.</span>", "palabras": [{"iast": "yadā", "sa": "यदा", "gram": "ind.", "es": "cuando"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "indriya-artheṣu", "sa": "इन्द्रियार्थेषु", "gram": "loc. pl. m. comp.", "es": "a los objetos de los sentidos", "ref": "visaya", "analisis": "indriya (sentido) + artha (objeto)"}, {"iast": "karmasu", "sa": "कर्मसु", "gram": "loc. pl. n.", "es": "a las acciones", "ref": "karma"}, {"iast": "anuṣajjate", "sa": "अनुषज्जते", "gram": "3 sg. pres. med.", "es": "se apega", "analisis": "anu-√sañj (adherirse, apegarse)"}, {"iast": "sarva-saṅkalpa-saṃnyāsī", "sa": "सर्वसङ्कल्पसंन्यासी", "gram": "nom. sg. m. comp.", "es": "que ha renunciado a toda intención", "ref": "sankalpa", "analisis": "sarva (toda) + saṅkalpa (intención) + saṃnyāsin (que renuncia)"}, {"iast": "yoga-ārūḍhaḥ", "sa": "योगारूढः", "gram": "nom. sg. m. comp.", "es": "el que ha ascendido al yoga", "ref": "yogarudha"}, {"iast": "tadā", "sa": "तदा", "gram": "ind.", "es": "entonces"}, {"iast": "ucyate", "sa": "उच्यते", "gram": "3 sg. pres. pas.", "es": "se dice", "analisis": "√vac (decir), pasiva"}], "nota": "<p>Es la definición del <em>yogārūḍha</em> que el verso anterior daba por supuesta. Sus tres rasgos son negativos: no apegarse a los objetos, no apegarse a las acciones, haber dejado toda intención. Que se nombren las acciones junto a los objetos indica que el apego puede estar en el propio obrar, no sólo en lo que se obtiene con él.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ascender-al-yoga"}, {"n": 5, "hablante": "krsna", "sa": ["उद्धरेदात्मनात्मानं नात्मानमवसादयेत् ।", "आत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः ॥५॥"], "iast": ["uddhared ātmanātmānaṃ nātmānam avasādayet", "ātmaiva hy ātmano bandhur ātmaiva ripur ātmanaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Que uno se eleve a sí mismo por sí mismo, y que no se hunda a sí mismo; pues uno mismo es su propio amigo, y uno mismo su propio enemigo.</span>", "palabras": [{"iast": "uddharet", "sa": "उद्धरेत्", "gram": "3 sg. opt. act.", "es": "que eleve", "analisis": "ud-√hṛ (sacar, levantar, rescatar)"}, {"iast": "ātmanā", "sa": "आत्मना", "gram": "instr. sg. m.", "es": "por sí mismo", "ref": "atman"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "ac. sg. m.", "es": "a sí mismo", "ref": "atman"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "ac. sg. m.", "es": "a sí mismo", "ref": "atman"}, {"iast": "avasādayet", "sa": "अवसादयेत्", "gram": "3 sg. opt. caus.", "es": "que hunda", "analisis": "causativo de ava-√sad (hundirse, desfallecer)"}, {"iast": "ātmā", "sa": "आत्मा", "gram": "nom. sg. m.", "es": "uno mismo", "ref": "atman"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "ātmanaḥ", "sa": "आत्मनः", "gram": "gen. sg. m.", "es": "de uno mismo", "ref": "atman"}, {"iast": "bandhuḥ", "sa": "बन्धुः", "gram": "nom. sg. m.", "es": "amigo", "analisis": "√bandh (atar): pariente, el que está unido a uno"}, {"iast": "ripuḥ", "sa": "रिपुः", "gram": "nom. sg. m.", "es": "enemigo"}], "nota": "<p>Siete veces aparece <em>ātman</em> en el verso, y seis en el siguiente (contando <em>anātman</em>): el juego es deliberado. El sentido básico es el reflexivo, «uno mismo», y la enseñanza es de responsabilidad: nadie puede subir por otro. <em>Uddharet</em> es «sacar, rescatar», como se saca a alguien del agua; <em>avasādayet</em>, «hacer que se hunda o desfallezca». <em>Bandhu</em> es el pariente y, de ahí, el amigo: el que está unido a uno.</p>", "interp": [{"titulo": "Salir del océano del saṃsāra", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende que uno ha de sacarse a sí mismo del <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">ciclo de renacimientos</a> en que está hundido, alcanzando el estado del que ha ascendido al yoga. Nadie más puede hacerlo: el amigo que ata con el afecto es, en realidad, causa de atadura; el único amigo que libera es uno mismo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La mente, amiga o enemiga", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee <em>ātman</em> como la mente en las apariciones que hablan del instrumento: con una mente desapegada de los objetos hay que elevar el sí-mismo; esa mente es su amiga, y la que se apega a los objetos, su enemiga.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Que eleve el sí-mismo por medio de la mente, y que no lo hunda; pues la mente es la amiga del sí-mismo, y la mente su enemiga.", "nota": "<p><em>Ātman</em> tiene en estos versos varios sentidos a la vez: el reflexivo «uno mismo», el sí-mismo y, según <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> (y, en el instrumental, <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>), la mente, que es el instrumento con el que uno se eleva o se hunde. Esta alternativa da a cada aparición un sentido distinto; la traducción principal, el reflexivo, que deja abierta la cuestión.</p>"}], "ens": "elevarse-a-si-mismo"}, {"n": 6, "hablante": "krsna", "sa": ["बन्धुरात्मात्मनस्तस्य येनात्मैवात्मना जितः ।", "अनात्मनस्तु शत्रुत्वे वर्तेतात्मैव शत्रुवत् ॥६॥"], "iast": ["bandhur ātmātmanas tasya yenātmaivātmanā jitaḥ", "anātmanas tu śatrutve vartetātmaiva śatruvat"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Para quien se ha vencido a sí mismo por sí mismo, uno mismo es su amigo; pero para quien no es dueño de sí, uno mismo se vuelve hostil, como un enemigo.</span>", "palabras": [{"iast": "bandhuḥ", "sa": "बन्धुः", "gram": "nom. sg. m.", "es": "amigo"}, {"iast": "ātmā", "sa": "आत्मा", "gram": "nom. sg. m.", "es": "uno mismo", "ref": "atman"}, {"iast": "ātmanaḥ", "sa": "आत्मनः", "gram": "gen. sg. m.", "es": "de sí mismo", "ref": "atman"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. m. pron.", "es": "de aquel"}, {"iast": "yena", "sa": "येन", "gram": "instr. sg. m. rel.", "es": "por quien"}, {"iast": "ātmā", "sa": "आत्मा", "gram": "nom. sg. m.", "es": "uno mismo", "ref": "atman"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "ātmanā", "sa": "आत्मना", "gram": "instr. sg. m.", "es": "por sí mismo", "ref": "atman"}, {"iast": "jitaḥ", "sa": "जितः", "gram": "nom. sg. m. ppp", "es": "vencido", "analisis": "√ji (vencer)"}, {"iast": "anātmanaḥ", "sa": "अनात्मनः", "gram": "gen. sg. m.", "es": "del que no es dueño de sí", "ref": "atman", "analisis": "an (sin) + ātman: el que no se posee a sí mismo"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "śatrutve", "sa": "शत्रुत्वे", "gram": "loc. sg. n.", "es": "en enemistad", "analisis": "śatru (enemigo) + -tva (condición)"}, {"iast": "varteta", "sa": "वर्तेत", "gram": "3 sg. opt. med.", "es": "se comporta", "analisis": "√vṛt (estar, conducirse)"}, {"iast": "ātmā", "sa": "आत्मा", "gram": "nom. sg. m.", "es": "uno mismo", "ref": "atman"}, {"iast": "śatruvat", "sa": "शत्रुवत्", "gram": "ind.", "es": "como un enemigo", "analisis": "śatru (enemigo) + -vat (como)"}], "nota": "<p>El verso explica el anterior: uno es su propio amigo o su propio enemigo según se haya vencido o no. <em>Anātman</em> no es aquí el «no-yo» de la filosofía budista, sino, como explican los comentaristas, el que no se ha ganado a sí mismo, el que no tiene dominio de sí. La imagen de la victoria sobre uno mismo prepara el «que se ha vencido» (<em>jitātman</em>) del verso siguiente.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "elevarse-a-si-mismo"}, {"n": 7, "hablante": "krsna", "sa": ["जितात्मनः प्रशान्तस्य परमात्मा समाहितः ।", "शीतोष्णसुखदुःखेषु तथा मानापमानयोः ॥७॥"], "iast": ["jitātmanaḥ praśāntasya paramātmā samāhitaḥ", "śītoṣṇa-sukha-duḥkheṣu tathā mānāpamānayoḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">En quien se ha vencido a sí mismo y está en calma, el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a> supremo permanece recogido, en el frío y el calor, en el <a class=\"t\" href=\"glosario.html#sukha\" data-t=\"sukha\">placer</a> y el <a class=\"t\" href=\"glosario.html#duhkha\" data-t=\"duhkha\">dolor</a>, y también en la honra y en la deshonra.</span>", "palabras": [{"iast": "jita-ātmanaḥ", "sa": "जितात्मनः", "gram": "gen. sg. m. comp.", "es": "del que se ha vencido a sí mismo", "ref": "atman", "analisis": "jita (vencido) + ātman (uno mismo): bahuvrīhi"}, {"iast": "praśāntasya", "sa": "प्रशान्तस्य", "gram": "gen. sg. m. ppp", "es": "del que está en calma", "analisis": "pra-√śam (calmarse por completo)"}, {"iast": "parama-ātmā", "sa": "परमात्मा", "gram": "nom. sg. m. comp.", "es": "el sí-mismo supremo", "ref": "atman", "analisis": "parama (supremo) + ātman; o bien param (supremamente) + ātmā (véanse las alternativas)"}, {"iast": "samāhitaḥ", "sa": "समाहितः", "gram": "nom. sg. m. ppp", "es": "recogido, concentrado", "ref": "samadhi", "analisis": "sam-ā-√dhā (poner junto, recoger): de la misma raíz que samādhi"}, {"iast": "śīta-uṣṇa-sukha-duḥkheṣu", "sa": "शीतोष्णसुखदुःखेषु", "gram": "loc. pl. n. comp.", "es": "en el frío y el calor, el placer y el dolor", "analisis": "śīta (frío) + uṣṇa (calor) + sukha (placer) + duḥkha (dolor)"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así también"}, {"iast": "māna-apamānayoḥ", "sa": "मानापमानयोः", "gram": "loc. du. m. comp.", "es": "en la honra y la deshonra", "analisis": "māna (honra) + apamāna (deshonra)"}], "nota": "<p>Los pares de opuestos de <a class=\"vref\" href=\"capitulo-02.html#v14\" data-v=\"2.14\">2.14</a> y <a class=\"vref\" href=\"capitulo-02.html#v38\" data-v=\"2.38\">2.38</a> vuelven aquí ampliados a lo social: la honra y la deshonra. <em>Samāhita</em>, «recogido, concentrado», es de la misma raíz que <em>samādhi</em>: lo disperso se reúne en un punto.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "El que se ha vencido a sí mismo y está en calma permanece del todo recogido en el frío y el calor, en el placer y el dolor, y también en la honra y en la deshonra.", "nota": "<p>Separando <em>param ātmā</em>, como propone <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> en primer lugar, y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> como segunda posibilidad: <em>param</em> como adverbio, «del todo» o «solamente» (sólo en quien se ha vencido), y <em>ātmā</em> como el sí-mismo del propio sabio. Así el verso no habla del sí-mismo supremo, sino del grado de recogimiento del que se ha vencido. La traducción principal sigue la lectura del compuesto <em>paramātman</em>, el sí-mismo supremo, como <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, en su primera explicación, también lee el compuesto, pero entiende por él el sí-mismo individual, «supremo» respecto de sus estados anteriores.</p>"}], "ens": "el-que-se-ha-vencido"}, {"n": 8, "hablante": "krsna", "sa": ["ज्ञानविज्ञानतृप्तात्मा कूटस्थो विजितेन्द्रियः ।", "युक्त इत्युच्यते योगी समलोष्टाश्मकाञ्चनः ॥८॥"], "iast": ["jñāna-vijñāna-tṛptātmā kūṭa-stho vijitendriyaḥ", "yukta ity ucyate yogī sama-loṣṭāśma-kāñcanaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> saciado de <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> y de conocimiento realizado, inmutable, vencedor de sus <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a>, para quien son iguales el terrón, la piedra y el oro, se dice que está <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a>.</span>", "palabras": [{"iast": "jñāna-vijñāna-tṛpta-ātmā", "sa": "ज्ञानविज्ञानतृप्तात्मा", "gram": "nom. sg. m. comp.", "es": "saciado de conocimiento y de conocimiento realizado", "ref": "jnana", "analisis": "jñāna (conocimiento) + vijñāna (conocimiento realizado) + tṛpta (saciado) + ātman"}, {"iast": "kūṭa-sthaḥ", "sa": "कूटस्थः", "gram": "nom. sg. m. comp.", "es": "inmutable", "analisis": "kūṭa (cima, montón, mazo) + stha (que está): que no cambia"}, {"iast": "vijita-indriyaḥ", "sa": "विजितेन्द्रियः", "gram": "nom. sg. m. comp.", "es": "vencedor de sus sentidos", "ref": "indriya", "analisis": "vijita (vencido) + indriya (sentido)"}, {"iast": "yuktaḥ", "sa": "युक्तः", "gram": "nom. sg. m. ppp", "es": "unido en yoga", "ref": "yukta"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cita)"}, {"iast": "ucyate", "sa": "उच्यते", "gram": "3 sg. pres. pas.", "es": "se dice", "analisis": "√vac (decir), pasiva"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "el yogui", "ref": "yogin"}, {"iast": "sama-loṣṭa-aśma-kāñcanaḥ", "sa": "समलोष्टाश्मकाञ्चनः", "gram": "nom. sg. m. comp.", "es": "para quien son iguales el terrón, la piedra y el oro", "analisis": "sama (igual) + loṣṭa (terrón) + aśman (piedra) + kāñcana (oro): bahuvrīhi"}], "nota": "<p><em>Jñāna</em> y <em>vijñāna</em> aparecen juntos aquí y en otros lugares (<a class=\"vref\" href=\"capitulo-03.html#v41\" data-v=\"3.41\">3.41</a>, <a class=\"vref\" href=\"capitulo-09.html#v1\" data-v=\"9.1\">9.1</a>, <a class=\"vref\" href=\"capitulo-18.html#v42\" data-v=\"18.42\">18.42</a>), y dan nombre al capítulo 7 (<a class=\"vref\" href=\"capitulo-07.html#v2\" data-v=\"7.2\">7.2</a>): el conocimiento y su realización, el saber recibido y el saber hecho propio. <em>Kūṭa-stha</em> es lo que permanece sin cambio; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo glosa aquí «inconmovible» (<em>aprakampya</em>). La imagen del yunque, sobre el que se golpea el hierro sin que cambie, viene de la tradición advaita, aunque los diccionarios dan para <em>kūṭa</em> «mazo», no «yunque» (véase la ficha <a class=\"t\" href=\"glosario.html#kutastha\" data-t=\"kutastha\">kūṭastha</a>). El terrón, la piedra y el oro resumen en una imagen la ecuanimidad: el yogui no deja de ver la diferencia, pero no la desea.</p>", "interp": [{"titulo": "Saber y experiencia", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> distingue <em>jñāna</em>, el conocimiento de lo que enseñan las escrituras, de <em>vijñāna</em>, la experiencia propia de eso mismo que las escrituras enseñan. El yogui está saciado de ambos; y es <em>kūṭa-stha</em> porque nada lo hace vacilar.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-que-se-ha-vencido"}, {"n": 9, "hablante": "krsna", "sa": ["सुहृन्मित्रार्युदासीनमध्यस्थद्वेष्यबन्धुषु ।", "साधुष्वपि च पापेषु समबुद्धिर्विशिष्यते ॥९॥"], "iast": ["suhṛn-mitrāry-udāsīna-madhyastha-dveṣya-bandhuṣu", "sādhuṣv api ca pāpeṣu sama-buddhir viśiṣyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Sobresale quien mira con el mismo <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> al que le quiere bien, al amigo y al enemigo, al indiferente y al mediador, al odioso y al pariente, a los buenos y también a los malvados.</span>", "palabras": [{"iast": "suhṛt-mitra-ari-udāsīna-madhyastha-dveṣya-bandhuṣu", "sa": "सुहृन्मित्रार्युदासीनमध्यस्थद्वेष्यबन्धुषु", "gram": "loc. pl. m. comp.", "es": "ante el que quiere bien, el amigo, el enemigo, el indiferente, el mediador, el odioso y el pariente", "analisis": "suhṛd (el que quiere bien) + mitra (amigo) + ari (enemigo) + udāsīna (indiferente) + madhyastha (mediador, el que está en medio) + dveṣya (odioso) + bandhu (pariente)"}, {"iast": "sādhuṣu", "sa": "साधुषु", "gram": "loc. pl. m.", "es": "ante los buenos"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "pāpeṣu", "sa": "पापेषु", "gram": "loc. pl. m.", "es": "ante los malvados", "ref": "papa"}, {"iast": "sama-buddhiḥ", "sa": "समबुद्धिः", "gram": "nom. sg. m. comp.", "es": "el de entendimiento igual", "ref": "buddhi", "analisis": "sama (igual) + buddhi (entendimiento): bahuvrīhi"}, {"iast": "viśiṣyate", "sa": "विशिष्यते", "gram": "3 sg. pres. pas.", "es": "sobresale", "analisis": "vi-√śiṣ (distinguir)"}], "nota": "<p>La ecuanimidad del verso anterior, aplicada ahora a las personas. La lista recorre todas las relaciones posibles: el <em>suhṛd</em>, que quiere el bien de uno sin esperar nada; el <em>mitra</em>, el amigo por afecto; el enemigo; el <em>udāsīna</em>, que no toma partido; el <em>madhyastha</em>, que media entre dos partes; el que es odioso y el pariente. Y al final, la prueba más difícil: buenos y malvados. Mirarlos «con el mismo entendimiento» no es aprobarlos igual, sino no dejar que el agrado o la aversión tuerzan el juicio (<a class=\"vref\" href=\"capitulo-05.html#v18\" data-v=\"5.18\">5.18</a>).</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-que-se-ha-vencido"}, {"n": 10, "hablante": "krsna", "sa": ["योगी युञ्जीत सततमात्मानं रहसि स्थितः ।", "एकाकी यतचित्तात्मा निराशीरपरिग्रहः ॥१०॥"], "iast": ["yogī yuñjīta satatam ātmānaṃ rahasi sthitaḥ", "ekākī yata-cittātmā nirāśīr aparigrahaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a>, retirado en un lugar apartado, solo, con el <a class=\"t\" href=\"glosario.html#citta\" data-t=\"citta\">pensamiento</a> y el cuerpo dominados, libre de esperanzas y sin posesiones, ha de concentrar sin cesar su <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> en el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>.</span>", "palabras": [{"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "el yogui", "ref": "yogin"}, {"iast": "yuñjīta", "sa": "युञ्जीत", "gram": "3 sg. opt. med.", "es": "ha de unir, ha de concentrar", "ref": "yoga", "analisis": "√yuj (uncir, unir); misma raíz que yoga"}, {"iast": "satatam", "sa": "सततम्", "gram": "ind.", "es": "sin cesar, siempre"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "ac. sg. m.", "es": "su mente; a sí mismo", "ref": "atman"}, {"iast": "rahasi", "sa": "रहसि", "gram": "loc. sg. n.", "es": "en un lugar apartado, en soledad"}, {"iast": "sthitaḥ", "sa": "स्थितः", "gram": "nom. sg. m. ppp.", "es": "situado, permaneciendo", "analisis": "√sthā (estar de pie, permanecer)"}, {"iast": "ekākī", "sa": "एकाकी", "gram": "nom. sg. m.", "es": "solo, sin compañía"}, {"iast": "yata-citta-ātmā", "sa": "यतचित्तात्मा", "gram": "nom. sg. m. comp.", "es": "con el pensamiento y el cuerpo dominados", "analisis": "yata (dominado), ppp de √yam (sujetar) + citta (pensamiento) + ātman (aquí, el cuerpo)"}, {"iast": "nirāśīḥ", "sa": "निराशीः", "gram": "nom. sg. m.", "es": "libre de esperanzas, sin esperar nada", "analisis": "nir (sin) + āśis (esperanza, deseo)"}, {"iast": "aparigrahaḥ", "sa": "अपरिग्रहः", "gram": "nom. sg. m.", "es": "sin posesiones", "analisis": "a (sin) + parigraha (posesión, lo que uno abarca), de pari-√grah (abarcar)"}], "nota": "<p>Empieza aquí la descripción detallada de la meditación que <a class=\"vref\" href=\"capitulo-05.html#v27\" data-v=\"5.27\">5.27</a>–<a class=\"vref\" href=\"capitulo-05.html#v28\" data-v=\"5.28\">5.28</a> había esbozado. <em>Yuñjīta ātmānam</em>: «que una, que concentre su <em>ātman</em>»; como en otros lugares, <em>ātman</em> no es aquí el sí-mismo en sentido filosófico, sino la mente que se concentra (véanse las alternativas). <em>Yata-cittātmā</em>, <em>nirāśīḥ</em>, «libre de esperanzas», y la renuncia a las posesiones repiten casi a la letra el retrato de <a class=\"vref\" href=\"capitulo-04.html#v21\" data-v=\"4.21\">4.21</a>. <em>Rahasi</em>: «en lo secreto, en un lugar apartado»; <em>ekākī</em>: «solo».</p>", "interp": [{"titulo": "La mente, no el sí-mismo", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> glosa aquí <em>ātmānam</em> como el órgano interno (<em>antaḥkaraṇa</em>), es decir, la mente que hay que concentrar, y en <em>yata-cittātmā</em> entiende <em>ātman</em> como el cuerpo, igual que en <a class=\"vref\" href=\"capitulo-04.html#v21\" data-v=\"4.21\">4.21</a>. Para él, este yogui es el que medita (<em>dhyāyin</em>), y que el verso lo quiera en un lugar apartado y solo indica, según él, que ha tomado ya la renuncia (<em>saṃnyāsa</em>): aun siendo renunciante, ha de concentrarse habiendo dejado toda posesión.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Un programa en ocho versos", "html": "<p>Los versos 6.10–6.17 forman una unidad: el lugar (6.10), el asiento (6.11), la concentración (6.12), la postura y la mirada (6.13), la actitud interior (6.14), el fruto (6.15) y la medida en la vida diaria (6.16–6.17). Es la descripción más concreta de una práctica de meditación en toda la Gītā.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "El yogui, retirado en un lugar apartado, solo, con el pensamiento y el cuerpo dominados, libre de esperanzas y sin posesiones, ha de concentrarse sin cesar en el sí-mismo.", "nota": "<p>Si <em>ātmānam</em> se entiende como el sí-mismo, objeto de la meditación, y no como la mente que medita. Gramaticalmente el verso admite las dos lecturas, y en la práctica coinciden: concentrar la mente es dirigirla hacia el sí-mismo.</p>"}], "ens": "sentarse-a-meditar"}, {"n": 11, "hablante": "krsna", "sa": ["शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः ।", "नात्युच्छ्रितं नातिनीचं चैलाजिनकुशोत्तरम् ॥११॥"], "iast": ["śucau deśe pratiṣṭhāpya sthiram āsanam ātmanaḥ", "nāty-ucchritaṃ nāti-nīcaṃ cailājina-kuśottaram"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">En un lugar limpio, asentando para sí un <a class=\"t\" href=\"glosario.html#asana\" data-t=\"asana\">asiento</a> firme, ni demasiado alto ni demasiado bajo, cubierto de tela, de piel y de hierba <a class=\"t\" href=\"glosario.html#kusa\" data-t=\"kusa\">kuśa</a>,</span>", "palabras": [{"iast": "śucau", "sa": "शुचौ", "gram": "loc. sg. m.", "es": "limpio, puro"}, {"iast": "deśe", "sa": "देशे", "gram": "loc. sg. m.", "es": "en un lugar"}, {"iast": "pratiṣṭhāpya", "sa": "प्रतिष्ठाप्य", "gram": "abs. caus.", "es": "estableciendo, colocando", "analisis": "prati-√sthā (asentarse), causativo"}, {"iast": "sthiram", "sa": "स्थिरम्", "gram": "ac. sg. n.", "es": "firme, estable"}, {"iast": "āsanam", "sa": "आसनम्", "gram": "ac. sg. n.", "es": "asiento", "ref": "asana", "analisis": "√ās (estar sentado)"}, {"iast": "ātmanaḥ", "sa": "आत्मनः", "gram": "gen. sg. m.", "es": "para sí, propio", "ref": "atman"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ati-ucchritam", "sa": "अत्युच्छ्रितम्", "gram": "ac. sg. n.", "es": "demasiado alto", "analisis": "ati (en exceso) + ucchrita (elevado), ppp de ud-√śri"}, {"iast": "ati-nīcam", "sa": "अतिनीचम्", "gram": "ac. sg. n.", "es": "demasiado bajo", "analisis": "ati (en exceso) + nīca (bajo)"}, {"iast": "caila-ajina-kuśa-uttaram", "sa": "चैलाजिनकुशोत्तरम्", "gram": "ac. sg. n. comp.", "es": "cubierto de tela, piel y hierba kuśa", "ref": "kusa", "analisis": "caila (tela) + ajina (piel, por lo común de antílope) + kuśa (hierba sagrada) + uttara (lo que está encima, la capa superior)"}], "nota": "<p><em>Śuci</em>: «limpio, puro», en sentido físico y ritual. <em>Ajina</em> es la piel de un animal, por lo común la del antílope negro (<em>kṛṣṇājina</em>), asiento tradicional de ascetas y estudiantes védicos. El compuesto <em>cailājina-kuśottaram</em> enumera tres capas sin decir su orden; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> las disponen en el orden inverso al de la enumeración —Śaṅkara lo advierte expresamente—: la hierba abajo, encima la piel y arriba la tela (véase la alternativa); Vedānta Deśika, en la escuela de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, pone la tela sobre un asiento de madera y la hierba encima de todo, por su pureza. Ni muy alto, para no temer una caída; ni muy bajo, para evitar los males que trae el contacto con el suelo: así explica la medida Ānandagiri, el glosador de Śaṅkara; Deśika habla sólo de comodidad.</p>", "interp": [{"titulo": "El lugar y el asiento en la Śvetāśvatara", "html": "<p>La <em>Śvetāśvatara Upaniṣad</em> (2.8–2.10) da instrucciones muy parecidas: mantener el cuerpo recto, con sus tres partes erguidas; recoger los sentidos en el corazón con la mente; y elegir para la práctica un lugar llano y limpio, libre de guijarros, de fuego y de arena, grato a la mente y que no hiera la vista, una cueva o un sitio resguardado del viento. La Gītā recoge esa tradición upaniṣádica de la meditación y la integra en su enseñanza.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "En un lugar limpio, asentando para sí un asiento firme, ni demasiado alto ni demasiado bajo, con hierba kuśa debajo, encima una piel y sobre ella una tela,", "nota": "<p>Con el orden que da la tradición, leyendo el compuesto de abajo arriba; así lo explican <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, que advierte que el orden es el inverso del enunciado, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>. Este último pide que la piel y la tela sean suaves, y recuerda la definición de Patañjali: el asiento ha de ser «firme y cómodo».</p>"}], "ens": "sentarse-a-meditar"}, {"n": 12, "hablante": "krsna", "sa": ["तत्रैकाग्रं मनः कृत्वा यतचित्तेन्द्रियक्रियः ।", "उपविश्यासने युञ्ज्याद्योगमात्मविशुद्धये ॥१२॥"], "iast": ["tatraikāgraṃ manaḥ kṛtvā yata-cittendriya-kriyaḥ", "upaviśyāsane yuñjyād yogam ātma-viśuddhaye"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">y sentado allí en el asiento, con la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> concentrada en un solo punto y dominando la actividad del <a class=\"t\" href=\"glosario.html#citta\" data-t=\"citta\">pensamiento</a> y de los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a>, ha de practicar el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> para purificarse.</span>", "palabras": [{"iast": "tatra", "sa": "तत्र", "gram": "ind.", "es": "allí"}, {"iast": "ekāgram", "sa": "एकाग्रम्", "gram": "ac. sg. n.", "es": "concentrada en un solo punto", "analisis": "eka (uno) + agra (punta, extremo)"}, {"iast": "manaḥ", "sa": "मनः", "gram": "ac. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "kṛtvā", "sa": "कृत्वा", "gram": "abs.", "es": "haciendo, poniendo", "analisis": "√kṛ (hacer)"}, {"iast": "yata-citta-indriya-kriyaḥ", "sa": "यतचित्तेन्द्रियक्रियः", "gram": "nom. sg. m. comp.", "es": "que domina la actividad del pensamiento y de los sentidos", "ref": "indriya", "analisis": "yata (dominado) + citta (pensamiento) + indriya (sentido) + kriyā (actividad)"}, {"iast": "upaviśya", "sa": "उपविश्य", "gram": "abs.", "es": "sentándose", "analisis": "upa-√viś (sentarse)"}, {"iast": "āsane", "sa": "आसने", "gram": "loc. sg. n.", "es": "en el asiento", "ref": "asana"}, {"iast": "yuñjyāt", "sa": "युञ्ज्यात्", "gram": "3 sg. opt. act.", "es": "ha de practicar", "analisis": "√yuj (unir, practicar el yoga)"}, {"iast": "yogam", "sa": "योगम्", "gram": "ac. sg. m.", "es": "el yoga", "ref": "yoga"}, {"iast": "ātma-viśuddhaye", "sa": "आत्मविशुद्धये", "gram": "dat. sg. f. comp.", "es": "para purificarse", "analisis": "ātman (uno mismo, la mente) + viśuddhi (purificación)"}], "nota": "<p><em>Ekāgra</em>: «de una sola punta», la mente reunida en un único objeto, sin dispersarse; es el término técnico de la concentración, que los <em>Yoga-sūtra</em> recogerán (<em>ekāgratā</em>, 3.11–3.12) y que su comentario clásico, el de Vyāsa, contará entre los estados de la mente. <em>Ātma-viśuddhaye</em>: «para la purificación de sí»; como en <a class=\"vref\" href=\"capitulo-05.html#v11\" data-v=\"5.11\">5.11</a>, lo que se purifica es la persona en su interior, la mente.</p>", "interp": [{"titulo": "La mente en un punto", "html": "<p>La palabra <em>ekāgra</em> reúne la técnica: no se trata de vaciar la mente, sino de darle un solo punto de apoyo. Los versos siguientes concretan ese punto: la mirada que no se dispersa (6.13) y la mente fija en Kṛṣṇa (6.14).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "sentarse-a-meditar"}, {"n": 13, "hablante": "krsna", "sa": ["समं कायशिरोग्रीवं धारयन्नचलं स्थिरः ।", "सम्प्रेक्ष्य नासिकाग्रं स्वं दिशश्चानवलोकयन् ॥१३॥"], "iast": ["samaṃ kāya-śiro-grīvaṃ dhārayann acalaṃ sthiraḥ", "samprekṣya nāsikāgraṃ svaṃ diśaś cānavalokayan"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Manteniendo el cuerpo, la cabeza y el cuello alineados e inmóviles, firme, con la mirada fija en la punta de su nariz y sin mirar a su alrededor,</span>", "palabras": [{"iast": "samam", "sa": "समम्", "gram": "ac. sg. n.", "es": "recto, alineado", "ref": "samatva"}, {"iast": "kāya-śiro-grīvam", "sa": "कायशिरोग्रीवम्", "gram": "ac. sg. n. comp.", "es": "el cuerpo, la cabeza y el cuello", "analisis": "kāya (cuerpo, tronco) + śiras (cabeza) + grīvā (cuello)"}, {"iast": "dhārayan", "sa": "धारयन्", "gram": "nom. sg. m. part. pres. caus.", "es": "manteniendo", "analisis": "√dhṛ (sostener), causativo"}, {"iast": "acalam", "sa": "अचलम्", "gram": "ac. sg. n.", "es": "inmóvil", "analisis": "a (no) + cala (que se mueve)"}, {"iast": "sthiraḥ", "sa": "स्थिरः", "gram": "nom. sg. m.", "es": "firme"}, {"iast": "samprekṣya", "sa": "सम्प्रेक्ष्य", "gram": "abs.", "es": "mirando fijamente", "analisis": "sam-pra-√īkṣ (mirar con atención)"}, {"iast": "nāsikā-agram", "sa": "नासिकाग्रम्", "gram": "ac. sg. n. comp.", "es": "la punta de la nariz", "analisis": "nāsikā (nariz) + agra (punta)"}, {"iast": "svam", "sa": "स्वम्", "gram": "ac. sg. n.", "es": "propia"}, {"iast": "diśaḥ", "sa": "दिशः", "gram": "ac. pl. f.", "es": "las direcciones, alrededor"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "anavalokayan", "sa": "अनवलोकयन्", "gram": "nom. sg. m. part. pres.", "es": "sin mirar", "analisis": "an (no) + ava-√lok (mirar)"}], "nota": "<p>La postura: el tronco, la cabeza y el cuello en una misma línea, sin moverse. <em>Samprekṣya nāsikāgram</em>: «mirando la punta de la nariz»; en <a class=\"vref\" href=\"capitulo-05.html#v27\" data-v=\"5.27\">5.27</a> la mirada se ponía «entre las cejas». En los dos casos se trata de lo mismo: fijar los ojos para que no arrastren a la mente hacia los objetos; de ahí la segunda mitad, «sin mirar a las direcciones», es decir, a su alrededor.</p>", "interp": [{"titulo": "Como si mirara la punta de la nariz", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> advierte que no se prescribe mirar la propia nariz, porque entonces la mente quedaría fija en ella y no en el sí-mismo; hay que entender «como si mirara»: lo que se pide es fijar y recoger la mirada, al servicio de la concentración de la mente. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> lo entiende como tener los ojos entornados; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, en cambio, como no cerrarlos, para no caer ni en el sueño ni en la dispersión.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Manteniendo el cuerpo, la cabeza y el cuello alineados e inmóviles, firme, con la mirada recogida, como dirigida a la punta de su nariz, y sin mirar a su alrededor,", "nota": "<p>Con la lectura de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, que entiende un «como si»: la punta de la nariz no es el objeto de la meditación, sino la dirección de una mirada que se recoge.</p>"}], "ens": "sentarse-a-meditar"}, {"n": 14, "hablante": "krsna", "sa": ["प्रशान्तात्मा विगतभीर्ब्रह्मचारिव्रते स्थितः ।", "मनः संयम्य मच्चित्तो युक्त आसीत मत्परः ॥१४॥"], "iast": ["praśāntātmā vigata-bhīr brahmacāri-vrate sthitaḥ", "manaḥ saṃyamya mac-citto yukta āsīta mat-paraḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">sereno, sin miedo, firme en el voto de <a class=\"t\" href=\"glosario.html#brahmacarya\" data-t=\"brahmacarya\">castidad</a>, dominando la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a>, con el <a class=\"t\" href=\"glosario.html#citta\" data-t=\"citta\">pensamiento</a> puesto en mí, ha de permanecer sentado, <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a>, teniéndome por meta suprema.</span>", "palabras": [{"iast": "praśānta-ātmā", "sa": "प्रशान्तात्मा", "gram": "nom. sg. m. comp.", "es": "sereno, de ánimo apaciguado", "ref": "santi", "analisis": "praśānta (apaciguado), ppp de pra-√śam + ātman (ánimo)"}, {"iast": "vigata-bhīḥ", "sa": "विगतभीः", "gram": "nom. sg. m. comp.", "es": "sin miedo", "analisis": "vigata (ido) + bhī (miedo)"}, {"iast": "brahmacāri-vrate", "sa": "ब्रह्मचारिव्रते", "gram": "loc. sg. n. comp.", "es": "en el voto del brahmacārin, en la castidad", "ref": "brahmacarya", "analisis": "brahmacārin (el estudiante védico, que guarda castidad) + vrata (voto)"}, {"iast": "sthitaḥ", "sa": "स्थितः", "gram": "nom. sg. m. ppp.", "es": "firme, establecido"}, {"iast": "manaḥ", "sa": "मनः", "gram": "ac. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "saṃyamya", "sa": "संयम्य", "gram": "abs.", "es": "dominando, sujetando", "analisis": "sam-√yam (sujetar)"}, {"iast": "mac-cittaḥ", "sa": "मच्चित्तः", "gram": "nom. sg. m. comp.", "es": "con el pensamiento en mí", "ref": "citta", "analisis": "mad (yo) + citta (pensamiento)"}, {"iast": "yuktaḥ", "sa": "युक्तः", "gram": "nom. sg. m.", "es": "unido en yoga", "ref": "yukta"}, {"iast": "āsīta", "sa": "आसीत", "gram": "3 sg. opt. med.", "es": "ha de permanecer sentado", "analisis": "√ās (estar sentado)"}, {"iast": "mat-paraḥ", "sa": "मत्परः", "gram": "nom. sg. m. comp.", "es": "que me tiene por meta suprema", "analisis": "mad (yo) + para (supremo, lo más alto)"}], "nota": "<p><em>Brahmacāri-vrata</em>: «el voto del <em>brahmacārin</em>», el estudiante védico que vive con su maestro y guarda castidad; aquí, sobre todo, la continencia (véase la ficha <a class=\"t\" href=\"glosario.html#brahmacarya\" data-t=\"brahmacarya\">brahmacarya</a>). <em>Mac-citta</em>, <em>mat-para</em>: «con el pensamiento en mí, que me tiene por lo más alto»; la meditación tiene un objeto, Kṛṣṇa mismo, y el verso anuncia así la devoción de los capítulos siguientes. La fórmula final, <em>yukta āsīta mat-paraḥ</em>, describe ya en <a class=\"vref\" href=\"capitulo-02.html#v61\" data-v=\"2.61\">2.61</a> al sabio de sabiduría firme, también tras un «dominando» (<em>saṃyamya</em>).</p>", "interp": [{"titulo": "El voto del estudiante", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende el voto del <em>brahmacārin</em> en sentido amplio: la castidad, el servicio al maestro y el comer de lo que se obtiene mendigando, es decir, la disciplina del estudiante védico. <em>Mat-para</em> es el que tiene al Señor supremo por lo más alto.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Meditar en el Señor", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> subraya la segunda mitad: aunque lo que el capítulo busca es la visión del propio sí-mismo, el que medita ha de estar sentado «pensando sólo en mí». Da la razón al comentar el verso siguiente: el Señor es el apoyo propicio (<em>śubhāśraya</em>) de la mente, y su contacto la purifica y la vuelve inmóvil; eso hace posible la concentración. Ya lo había explicado a propósito de <a class=\"vref\" href=\"capitulo-02.html#v61\" data-v=\"2.61\">2.61</a>.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Un eco de 2.61", "html": "<p>La fórmula <em>yukta āsīta mat-paraḥ</em>, «permanezca sentado, unido en yoga, teniéndome por meta», aparece ya en <a class=\"vref\" href=\"capitulo-02.html#v61\" data-v=\"2.61\">2.61</a>, en el retrato del sabio de sabiduría firme que domina sus sentidos. Lo que allí era un rasgo del sabio es aquí un paso de la práctica.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "sereno, sin miedo, firme en el voto del estudiante védico, dominando la mente, con el pensamiento puesto en mí, ha de permanecer sentado, unido en yoga, teniéndome por meta suprema.", "nota": "<p><em>Brahmacāri-vrata</em> en su sentido amplio: la disciplina entera del <em>brahmacārin</em>, que incluye la castidad, pero también el servicio al maestro y el comer de lo que se obtiene mendigando; así lo entienden <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>.</p>"}], "ens": "sentarse-a-meditar"}, {"n": 15, "hablante": "krsna", "sa": ["युञ्जन्नेवं सदात्मानं योगी नियतमानसः ।", "शान्तिं निर्वाणपरमां मत्संस्थामधिगच्छति ॥१५॥"], "iast": ["yuñjann evaṃ sadātmānaṃ yogī niyata-mānasaḥ", "śāntiṃ nirvāṇa-paramāṃ mat-saṃsthām adhigacchati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Concentrando así siempre su mente, el <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> de mente sujeta alcanza la <a class=\"t\" href=\"glosario.html#santi\" data-t=\"santi\">paz</a> que culmina en el <a class=\"t\" href=\"glosario.html#nirvana\" data-t=\"nirvana\">nirvāṇa</a> y que reside en mí.</span>", "palabras": [{"iast": "yuñjan", "sa": "युञ्जन्", "gram": "nom. sg. m. part. pres.", "es": "uniendo, concentrando", "analisis": "√yuj (unir)"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "sadā", "sa": "सदा", "gram": "ind.", "es": "siempre"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "ac. sg. m.", "es": "su mente; a sí mismo", "ref": "atman"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "el yogui", "ref": "yogin"}, {"iast": "niyata-mānasaḥ", "sa": "नियतमानसः", "gram": "nom. sg. m. comp.", "es": "de mente sujeta", "ref": "manas", "analisis": "niyata (sujeto, regulado), ppp de ni-√yam + mānasa (mente)"}, {"iast": "śāntim", "sa": "शान्तिम्", "gram": "ac. sg. f.", "es": "la paz", "ref": "santi"}, {"iast": "nirvāṇa-paramām", "sa": "निर्वाणपरमाम्", "gram": "ac. sg. f. comp.", "es": "que culmina en el nirvāṇa", "ref": "nirvana", "analisis": "nirvāṇa (extinción) + parama (supremo, término)"}, {"iast": "mat-saṃsthām", "sa": "मत्संस्थाम्", "gram": "ac. sg. f. comp.", "es": "que reside en mí", "analisis": "mad (yo) + saṃsthā (morada, permanencia)"}, {"iast": "adhigacchati", "sa": "अधिगच्छति", "gram": "3 sg. pres. act.", "es": "alcanza", "analisis": "adhi-√gam (alcanzar)"}], "nota": "<p><em>Nirvāṇa-paramā</em>: «cuyo término supremo es el nirvāṇa», la paz que desemboca en la extinción; <em>mat-saṃsthā</em>: «que tiene en mí su asiento». El verso une el lenguaje del capítulo 5 (la extinción en brahman, <a class=\"vref\" href=\"capitulo-05.html#v24\" data-v=\"5.24\">5.24</a>–<a class=\"vref\" href=\"capitulo-05.html#v26\" data-v=\"5.26\">5.26</a>) con el de la devoción: la paz del yogui está en Kṛṣṇa.</p>", "interp": [{"titulo": "El nirvāṇa en Kṛṣṇa", "html": "<p>En <a class=\"vref\" href=\"capitulo-02.html#v72\" data-v=\"2.72\">2.72</a> y en <a class=\"vref\" href=\"capitulo-05.html#v24\" data-v=\"5.24\">5.24</a>–<a class=\"vref\" href=\"capitulo-05.html#v26\" data-v=\"5.26\">5.26</a> el nirvāṇa era «en brahman»; aquí la paz que culmina en el nirvāṇa «reside en mí». La Gītā no opone las dos fórmulas: el capítulo 14 dirá que Kṛṣṇa es el fundamento de brahman (<a class=\"vref\" href=\"capitulo-14.html#v27\" data-v=\"14.27\">14.27</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "sentarse-a-meditar"}, {"n": 16, "hablante": "krsna", "sa": ["नात्यश्नतस्तु योगोऽस्ति न चैकान्तमनश्नतः ।", "न चातिस्वप्नशीलस्य जाग्रतो नैव चार्जुन ॥१६॥"], "iast": ["nāty-aśnatas tu yogo 'sti na caikāntam anaśnataḥ", "na cāti-svapna-śīlasya jāgrato naiva cārjuna"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> no es para el que come en exceso ni para el que no come nada, ni para el que duerme demasiado ni tampoco para el que vela demasiado, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ati-aśnataḥ", "sa": "अत्यश्नतः", "gram": "gen. sg. m. part. pres.", "es": "del que come en exceso", "analisis": "ati (en exceso) + aśnat (que come), de √aś (comer)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "yogaḥ", "sa": "योगः", "gram": "nom. sg. m.", "es": "el yoga", "ref": "yoga"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres.", "es": "es, hay"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "ekāntam", "sa": "एकान्तम्", "gram": "ind.", "es": "por completo, en absoluto", "analisis": "eka (uno) + anta (extremo)"}, {"iast": "anaśnataḥ", "sa": "अनश्नतः", "gram": "gen. sg. m. part. pres.", "es": "del que no come", "analisis": "an (no) + aśnat (que come)"}, {"iast": "ati-svapna-śīlasya", "sa": "अतिस्वप्नशीलस्य", "gram": "gen. sg. m. comp.", "es": "del que tiene costumbre de dormir demasiado", "analisis": "ati (en exceso) + svapna (sueño) + śīla (costumbre, hábito)"}, {"iast": "jāgrataḥ", "sa": "जाग्रतः", "gram": "gen. sg. m. part. pres.", "es": "del que vela", "analisis": "√jāgṛ (estar despierto)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "tampoco (con na)"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}], "nota": "<p><em>Ati</em> («en exceso») va con «comer» y con «dormir», y se sobrentiende con «velar»: la segunda mitad opone el que duerme demasiado al que no duerme lo bastante. <em>Ekāntam anaśnataḥ</em>: «del que no come en absoluto», el ayuno extremo. Tras la instrucción sobre el asiento y la postura, Kṛṣṇa pasa a la vida diaria del que medita.</p>", "interp": [{"titulo": "La medida justa", "html": "<p>El rechazo de los dos extremos, el exceso y la mortificación, recuerda inevitablemente el «camino medio» con que, según la tradición budista, el Buddha empezó a predicar, después de haber probado y abandonado el ascetismo extremo. En la Gītā la medida no es una doctrina aparte, sino una condición práctica: un cuerpo saciado o agotado no puede concentrarse. Ya en <a class=\"vref\" href=\"capitulo-04.html#v30\" data-v=\"4.30\">4.30</a> se hablaba de quienes regulan su alimento.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-medida-justa"}, {"n": 17, "hablante": "krsna", "sa": ["युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु ।", "युक्तस्वप्नावबोधस्य योगो भवति दुःखहा ॥१७॥"], "iast": ["yuktāhāra-vihārasya yukta-ceṣṭasya karmasu", "yukta-svapnāvabodhasya yogo bhavati duḥkha-hā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Para quien es moderado en la comida y en el esparcimiento, moderado en el esfuerzo de sus <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a>, moderado en el sueño y en la vigilia, el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> se vuelve destructor del <a class=\"t\" href=\"glosario.html#duhkha\" data-t=\"duhkha\">sufrimiento</a>.</span>", "palabras": [{"iast": "yukta-āhāra-vihārasya", "sa": "युक्ताहारविहारस्य", "gram": "gen. sg. m. comp.", "es": "del que es moderado en la comida y en el esparcimiento", "ref": "yukta", "analisis": "yukta (medido, moderado) + āhāra (alimento) + vihāra (paseo, esparcimiento), de vi-√hṛ (moverse a gusto)"}, {"iast": "yukta-ceṣṭasya", "sa": "युक्तचेष्टस्य", "gram": "gen. sg. m. comp.", "es": "del que es moderado en su esfuerzo", "analisis": "yukta (moderado) + ceṣṭā (movimiento, esfuerzo), de √ceṣṭ (moverse)"}, {"iast": "karmasu", "sa": "कर्मसु", "gram": "loc. pl. n.", "es": "en las acciones", "ref": "karma"}, {"iast": "yukta-svapna-avabodhasya", "sa": "युक्तस्वप्नावबोधस्य", "gram": "gen. sg. m. comp.", "es": "del que es moderado en el sueño y en la vigilia", "analisis": "yukta (moderado) + svapna (sueño) + avabodha (despertar, vigilia)"}, {"iast": "yogaḥ", "sa": "योगः", "gram": "nom. sg. m.", "es": "el yoga", "ref": "yoga"}, {"iast": "bhavati", "sa": "भवति", "gram": "3 sg. pres.", "es": "llega a ser"}, {"iast": "duḥkha-hā", "sa": "दुःखहा", "gram": "nom. sg. m. comp.", "es": "destructor del sufrimiento", "ref": "duhkha", "analisis": "duḥkha (sufrimiento) + han (que mata, que destruye), de √han"}], "nota": "<p>El verso juega con la palabra <em>yukta</em>, que se repite tres veces: «unido» o «disciplinado» en el sentido del yoga, y aquí también «medido, ajustado». El que es <em>yukta</em> en lo pequeño (la comida, el sueño, el esfuerzo) puede llegar a ser <em>yukta</em> en el yoga. <em>Vihāra</em>: «paseo, movimiento, esparcimiento». <em>Duḥkha-hā</em>: «matador del sufrimiento»; el capítulo definirá el yoga precisamente como la separación del contacto con el sufrimiento (<a class=\"vref\" href=\"capitulo-06.html#v23\" data-v=\"6.23\">6.23</a>).</p>", "interp": [{"titulo": "Moderado: yukta", "html": "<p>Traducimos <em>yukta</em> por «moderado», pero el sánscrito dice más: la misma palabra que designa al yogui que ha alcanzado la unión (<a class=\"vref\" href=\"capitulo-05.html#v8\" data-v=\"5.8\">5.8</a>, <a class=\"vref\" href=\"capitulo-06.html#v8\" data-v=\"6.8\">6.8</a>) designa aquí al que lleva una vida ordenada. La disciplina interior y la medida exterior son, para la Gītā, una sola cosa.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-medida-justa"}, {"n": 18, "hablante": "krsna", "sa": ["यदा विनियतं चित्तमात्मन्येवावतिष्ठते ।", "निःस्पृहः सर्वकामेभ्यो युक्त इत्युच्यते तदा ॥१८॥"], "iast": ["yadā viniyataṃ cittam ātmany evāvatiṣṭhate", "niḥspṛhaḥ sarva-kāmebhyo yukta ity ucyate tadā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Cuando el <a class=\"t\" href=\"glosario.html#citta\" data-t=\"citta\">pensamiento</a>, bien dominado, reposa sólo en el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>, libre del anhelo de todos los <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseos</a>, entonces se dice que está <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a>.</span>", "palabras": [{"iast": "yadā", "sa": "यदा", "gram": "ind.", "es": "cuando"}, {"iast": "viniyatam", "sa": "विनियतम्", "gram": "nom. sg. n. ppp", "es": "bien dominado", "analisis": "vi-ni-√yam (sujetar, refrenar)"}, {"iast": "cittam", "sa": "चित्तम्", "gram": "nom. sg. n.", "es": "el pensamiento", "ref": "citta", "analisis": "de √cit (percibir, pensar)"}, {"iast": "ātmani", "sa": "आत्मनि", "gram": "loc. sg. m.", "es": "en el sí-mismo", "ref": "atman"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "solo, únicamente"}, {"iast": "avatiṣṭhate", "sa": "अवतिष्ठते", "gram": "3 sg. pres. med.", "es": "reposa, permanece", "analisis": "ava-√sthā (quedarse, asentarse)"}, {"iast": "niḥspṛhaḥ", "sa": "निःस्पृहः", "gram": "nom. sg. m.", "es": "sin anhelo", "analisis": "nis (sin) + spṛhā (anhelo, avidez)"}, {"iast": "sarva-kāmebhyaḥ", "sa": "सर्वकामेभ्यः", "gram": "abl. pl. m. comp.", "es": "de todos los deseos", "ref": "kama", "analisis": "sarva (todo) + kāma (deseo)"}, {"iast": "yuktaḥ", "sa": "युक्तः", "gram": "nom. sg. m. ppp", "es": "unido (en yoga)", "ref": "yukta", "analisis": "√yuj (uncir, unir)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cierra la cita)"}, {"iast": "ucyate", "sa": "उच्यते", "gram": "3 sg. pres. pas.", "es": "se dice", "analisis": "√vac (decir)"}, {"iast": "tadā", "sa": "तदा", "gram": "ind.", "es": "entonces"}], "nota": "<p><em>Citta</em>: «pensamiento», el término del yoga para la mente en su actividad (véase la ficha). <em>Viniyata</em>: «bien sujeto, refrenado», de la misma raíz que <em>niyama</em>. <em>Niḥspṛha</em>: «sin avidez»; ya en <a class=\"vref\" href=\"capitulo-02.html#v71\" data-v=\"2.71\">2.71</a> el que alcanza la paz vive «sin anhelo». El verso da una definición: <em>yukta</em>, «unido en yoga», es el que tiene el pensamiento asentado en el sí-mismo y nada más.</p>", "interp": [{"titulo": "Una definición del yogui", "html": "<p>Los versos 6.10–6.17 describen qué hace el que medita: el lugar, el asiento, la postura, la mirada, la medida en comer y dormir. Éste dice cuándo lo ha logrado: no por la postura, sino cuando el pensamiento ya no sale del sí-mismo. El verso siguiente da la imagen de ese estado.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-lampara-sin-viento"}, {"n": 19, "hablante": "krsna", "sa": ["यथा दीपो निवातस्थो नेङ्गते सोपमा स्मृता ।", "योगिनो यतचित्तस्य युञ्जतो योगमात्मनः ॥१९॥"], "iast": ["yathā dīpo nivāta-stho neṅgate sopamā smṛtā", "yogino yata-cittasya yuñjato yogam ātmanaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Como una lámpara al abrigo del viento, que no vacila: ésa es la comparación que se recuerda para el <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> de <a class=\"t\" href=\"glosario.html#citta\" data-t=\"citta\">pensamiento</a> dominado que se ejercita en el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> del sí-mismo.</span>", "palabras": [{"iast": "yathā", "sa": "यथा", "gram": "ind.", "es": "como"}, {"iast": "dīpaḥ", "sa": "दीपः", "gram": "nom. sg. m.", "es": "una lámpara", "analisis": "de √dīp (arder, brillar)"}, {"iast": "nivāta-sthaḥ", "sa": "निवातस्थः", "gram": "nom. sg. m. comp.", "es": "situada donde no hay viento", "analisis": "nivāta (sin viento, abrigado) + stha (que está)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "iṅgate", "sa": "इङ्गते", "gram": "3 sg. pres. med.", "es": "vacila, oscila", "analisis": "√iṅg (moverse, agitarse)"}, {"iast": "sā", "sa": "सा", "gram": "nom. sg. f. pron.", "es": "ésa"}, {"iast": "upamā", "sa": "उपमा", "gram": "nom. sg. f.", "es": "la comparación"}, {"iast": "smṛtā", "sa": "स्मृता", "gram": "nom. sg. f. ppp", "es": "se recuerda, es la tradicional", "analisis": "√smṛ (recordar)"}, {"iast": "yoginaḥ", "sa": "योगिनः", "gram": "gen. sg. m.", "es": "del yogui", "ref": "yogin"}, {"iast": "yata-cittasya", "sa": "यतचित्तस्य", "gram": "gen. sg. m. comp.", "es": "de pensamiento dominado", "ref": "citta", "analisis": "yata (dominado), ppp de √yam + citta (pensamiento)"}, {"iast": "yuñjataḥ", "sa": "युञ्जतः", "gram": "gen. sg. m. ppa", "es": "que se ejercita", "analisis": "√yuj (uncir, ejercitarse en el yoga)"}, {"iast": "yogam", "sa": "योगम्", "gram": "ac. sg. m.", "es": "en el yoga", "ref": "yoga"}, {"iast": "ātmanaḥ", "sa": "आत्मनः", "gram": "gen. sg. m.", "es": "del sí-mismo", "ref": "atman"}], "nota": "<p><em>Nivāta-stha</em>: «que está donde no hay viento». <em>Iṅgate</em>: «se agita, vacila», dicho de la llama. <em>Smṛtā</em>: «recordada», es decir, la comparación que se ha transmitido, la consabida. <em>Yogam ātmanaḥ</em>: puede entenderse «el yoga del sí-mismo» (que tiene el sí-mismo por objeto) o, con <em>yuñjataḥ</em>, «que ejercita su propio yoga»; el sentido no cambia.</p>", "interp": [{"titulo": "La comparación de los que conocen el yoga", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> glosa <em>smṛtā</em> como «pensada por los que conocen el yoga»: es la imagen con que ellos describen el pensamiento que no se mueve. Lo que no vacila es el pensamiento del que medita en el sí-mismo, como no vacila la llama que no recibe viento.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La lámpara", "html": "<p>La imagen dice dos cosas a la vez. La llama sigue ardiendo: el pensamiento recogido no se apaga ni se duerme, sigue iluminando. Pero no se mueve, porque nada la sacude desde fuera. Es la forma positiva de lo que el capítulo 2 describía como la tortuga que retira sus miembros (<a class=\"vref\" href=\"capitulo-02.html#v58\" data-v=\"2.58\">2.58</a>): no sólo retirarse de los objetos, sino quedar encendido y quieto.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-lampara-sin-viento"}, {"n": 20, "hablante": "krsna", "sa": ["यत्रोपरमते चित्तं निरुद्धं योगसेवया ।", "यत्र चैवात्मनात्मानं पश्यन्नात्मनि तुष्यति ॥२०॥"], "iast": ["yatroparamate cittaṃ niruddhaṃ yoga-sevayā", "yatra caivātmanātmānaṃ paśyann ātmani tuṣyati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Aquel estado en que el <a class=\"t\" href=\"glosario.html#citta\" data-t=\"citta\">pensamiento</a>, refrenado por la práctica del <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>, se aquieta; en que, viendo el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a> por el sí-mismo, uno se complace en el sí-mismo;</span>", "palabras": [{"iast": "yatra", "sa": "यत्र", "gram": "ind.", "es": "en el que (el estado en que)"}, {"iast": "uparamate", "sa": "उपरमते", "gram": "3 sg. pres. med.", "es": "se aquieta, cesa", "analisis": "upa-√ram (detenerse, aquietarse)"}, {"iast": "cittam", "sa": "चित्तम्", "gram": "nom. sg. n.", "es": "el pensamiento", "ref": "citta"}, {"iast": "niruddham", "sa": "निरुद्धम्", "gram": "nom. sg. n. ppp", "es": "refrenado", "analisis": "ni-√rudh (contener, detener); de ahí *nirodha*"}, {"iast": "yoga-sevayā", "sa": "योगसेवया", "gram": "instr. sg. f. comp.", "es": "por la práctica del yoga", "ref": "yoga", "analisis": "yoga + sevā (práctica asidua, cultivo)"}, {"iast": "yatra", "sa": "यत्र", "gram": "ind.", "es": "en el que"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "ātmanā", "sa": "आत्मना", "gram": "instr. sg. m.", "es": "por el sí-mismo", "ref": "atman"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "ac. sg. m.", "es": "al sí-mismo", "ref": "atman"}, {"iast": "paśyan", "sa": "पश्यन्", "gram": "nom. sg. m. ppa", "es": "viendo", "analisis": "√paś / dṛś (ver)"}, {"iast": "ātmani", "sa": "आत्मनि", "gram": "loc. sg. m.", "es": "en el sí-mismo", "ref": "atman"}, {"iast": "tuṣyati", "sa": "तुष्यति", "gram": "3 sg. pres. act.", "es": "se complace", "analisis": "√tuṣ (contentarse)"}], "nota": "<p>Empieza aquí una sola frase que llega hasta <a class=\"vref\" href=\"capitulo-06.html#v23\" data-v=\"6.23\">6.23</a>: tres versos describen «aquel estado en que…» (<em>yatra</em>… <em>yatra</em>…) y el cuarto lo nombra: eso es el yoga. <em>Niruddha</em>: «refrenado, detenido»; el sustantivo de esta raíz, <em>nirodha</em>, es el que usarán los <em>Yoga-sūtra</em> para definir el yoga. <em>Ātmanātmānam</em>: «al sí-mismo por el sí-mismo», la misma construcción reflexiva de <a class=\"vref\" href=\"capitulo-06.html#v5\" data-v=\"6.5\">6.5</a>; cerca de <a class=\"vref\" href=\"capitulo-02.html#v55\" data-v=\"2.55\">2.55</a>, el que «está contento en el sí-mismo por el sí-mismo».</p>", "interp": [{"titulo": "Ver con la mente purificada", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende el instrumental <em>ātmanā</em> como la mente (el órgano interno) purificada por la concentración, y el <em>ātmānam</em> que se ve como el sí-mismo supremo, la conciencia que es luz. Uno no se complace en otra cosa, sino en el sí-mismo mismo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El vocabulario del Yoga", "html": "<p><em>Citta</em> y <em>nirodha</em>, el sustantivo de <em>niruddha</em>, son las dos palabras con que los <em>Yoga-sūtra</em> de Patañjali definen el yoga en su segundo aforismo: <em>yogaś citta-vṛtti-nirodhaḥ</em>, «el yoga es el refrenamiento de las fluctuaciones del pensamiento» (1.2). La Gītā no es todavía ese sistema, pero comparte su vocabulario: aquí el pensamiento «refrenado» se aquieta por la práctica.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Aquel estado en que el pensamiento, refrenado por la práctica del yoga, se aquieta; en que, viendo con la mente el sí-mismo, uno se complace en el sí-mismo;", "nota": "<p>Tomando <em>ātmanā</em> como «con la mente», el órgano interno, como lo glosa <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>: el instrumento con que se ve no es el mismo sí-mismo que se ve. La traducción principal conserva el juego reflexivo del sánscrito, <em>ātmanātmānam</em>, «el sí-mismo por el sí-mismo».</p>"}], "ens": "la-desunion-del-dolor"}, {"n": 21, "hablante": "krsna", "sa": ["सुखमात्यन्तिकं यत्तद्बुद्धिग्राह्यमतीन्द्रियम् ।", "वेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वतः ॥२१॥"], "iast": ["sukham ātyantikaṃ yat tad buddhi-grāhyam atīndriyam", "vetti yatra na caivāyaṃ sthitaś calati tattvataḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">en que conoce esa <a class=\"t\" href=\"glosario.html#sukha\" data-t=\"sukha\">dicha</a> infinita que capta el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> y está más allá de los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a>, y en que, una vez asentado, ya no se aparta de la verdad;</span>", "palabras": [{"iast": "sukham", "sa": "सुखम्", "gram": "ac. sg. n.", "es": "la dicha", "ref": "sukha"}, {"iast": "ātyantikam", "sa": "आत्यन्तिकम्", "gram": "ac. sg. n.", "es": "infinita, absoluta", "analisis": "de atyanta (que va más allá del fin)"}, {"iast": "yat", "sa": "यत्", "gram": "ac. sg. n. pron. rel.", "es": "que"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "esa"}, {"iast": "buddhi-grāhyam", "sa": "बुद्धिग्राह्यम्", "gram": "ac. sg. n. comp.", "es": "que capta el entendimiento", "ref": "buddhi", "analisis": "buddhi (entendimiento) + grāhya (que ha de captarse), de √grah (tomar)"}, {"iast": "atīndriyam", "sa": "अतीन्द्रियम्", "gram": "ac. sg. n. comp.", "es": "más allá de los sentidos", "ref": "indriya", "analisis": "ati (más allá) + indriya (sentido)"}, {"iast": "vetti", "sa": "वेत्ति", "gram": "3 sg. pres. act.", "es": "conoce", "analisis": "√vid (saber)"}, {"iast": "yatra", "sa": "यत्र", "gram": "ind.", "es": "en el que"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "éste (el yogui)"}, {"iast": "sthitaḥ", "sa": "स्थितः", "gram": "nom. sg. m. ppp", "es": "asentado", "analisis": "√sthā (estar, permanecer)"}, {"iast": "calati", "sa": "चलति", "gram": "3 sg. pres. act.", "es": "se aparta, se mueve", "analisis": "√cal (moverse)"}, {"iast": "tattvataḥ", "sa": "तत्त्वतः", "gram": "ind.", "es": "de la verdad", "analisis": "tattva (lo que es tal cual, la verdad) + -tas (desde)"}], "nota": "<p><em>Ātyantika</em>: «que va más allá del fin», es decir, sin término; la dicha de los sentidos, en cambio, «tiene principio y fin» (<a class=\"vref\" href=\"capitulo-05.html#v22\" data-v=\"5.22\">5.22</a>). <em>Buddhi-grāhya</em>: «captable por el entendimiento», no por los sentidos. <em>Tattvataḥ</em>: «desde la verdad», con verbo de movimiento: no se aparta de lo que es.</p>", "interp": [{"titulo": "Una dicha que no viene de fuera", "html": "<p>El verso retoma lo que el capítulo 5 había dicho de la dicha interior (<a class=\"vref\" href=\"capitulo-05.html#v21\" data-v=\"5.21\">5.21</a>, <a class=\"vref\" href=\"capitulo-05.html#v24\" data-v=\"5.24\">5.24</a>) y lo precisa: no es un placer más, sino otra clase de dicha, que no pasa por los sentidos y no se agota. La Gītā no describe la meta como privación: el que medita no renuncia a la dicha, sino que encuentra una mayor.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-desunion-del-dolor"}, {"n": 22, "hablante": "krsna", "sa": ["यं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः ।", "यस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते ॥२२॥"], "iast": ["yaṃ labdhvā cāparaṃ lābhaṃ manyate nādhikaṃ tataḥ", "yasmin sthito na duḥkhena guruṇāpi vicālyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">aquel que, una vez alcanzado, hace que ninguna otra ganancia parezca mayor, y en el que, asentado, ni el <a class=\"t\" href=\"glosario.html#duhkha\" data-t=\"duhkha\">dolor</a> más grave lo conmueve:</span>", "palabras": [{"iast": "yam", "sa": "यम्", "gram": "ac. sg. m. pron. rel.", "es": "el cual"}, {"iast": "labdhvā", "sa": "लब्ध्वा", "gram": "abs.", "es": "una vez alcanzado", "analisis": "√labh (obtener)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "aparam", "sa": "अपरम्", "gram": "ac. sg. m.", "es": "otra"}, {"iast": "lābham", "sa": "लाभम्", "gram": "ac. sg. m.", "es": "ganancia", "analisis": "de √labh"}, {"iast": "manyate", "sa": "मन्यते", "gram": "3 sg. pres. med.", "es": "considera", "analisis": "√man (pensar)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "adhikam", "sa": "अधिकम्", "gram": "ac. sg. m.", "es": "mayor"}, {"iast": "tataḥ", "sa": "ततः", "gram": "ind.", "es": "que eso"}, {"iast": "yasmin", "sa": "यस्मिन्", "gram": "loc. sg. m. pron. rel.", "es": "en el cual"}, {"iast": "sthitaḥ", "sa": "स्थितः", "gram": "nom. sg. m. ppp", "es": "asentado"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "duḥkhena", "sa": "दुःखेन", "gram": "instr. sg. n.", "es": "por el dolor", "ref": "duhkha"}, {"iast": "guruṇā", "sa": "गुरुणा", "gram": "instr. sg. n.", "es": "grave, pesado"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "ni siquiera"}, {"iast": "vicālyate", "sa": "विचाल्यते", "gram": "3 sg. pres. pas. caus.", "es": "es conmovido", "analisis": "vi-√cal, causativo (hacer moverse, sacudir)"}], "nota": "<p><em>Yam</em>: masculino, concuerda con el <em>yoga</em> que se nombrará en el verso siguiente, o con un «estado» sobrentendido. <em>Guru</em>: «pesado, grave», la misma palabra que «maestro», aquí en su sentido físico. <em>Vicālyate</em>: «es sacudido, apartado»; continúa la imagen de la lámpara que no vacila (<a class=\"vref\" href=\"capitulo-06.html#v19\" data-v=\"6.19\">6.19</a>).</p>", "interp": [{"titulo": "Lo que el dolor no mueve", "html": "<p>El verso no dice que el yogui deje de sentir dolor, sino que el dolor, por grande que sea, no lo saca de donde está. Es la ecuanimidad del capítulo 2 —«igual en el placer y en el dolor» (<a class=\"vref\" href=\"capitulo-02.html#v15\" data-v=\"2.15\">2.15</a>, <a class=\"vref\" href=\"capitulo-02.html#v38\" data-v=\"2.38\">2.38</a>)— vista desde dentro: quien ha encontrado una dicha mayor ya no necesita huir del dolor ni perseguir otra ganancia.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "la-desunion-del-dolor"}, {"n": 23, "hablante": "krsna", "sa": ["तं विद्याद्दुःखसंयोगवियोगं योगसंज्ञितम् ।", "स निश्चयेन योक्तव्यो योगोऽनिर्विण्णचेतसा ॥२३॥"], "iast": ["taṃ vidyād duḥkha-saṃyoga-viyogaṃ yoga-saṃjñitam", "sa niścayena yoktavyo yogo 'nirviṇṇa-cetasā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">sépase que eso, la desunión de la unión con el <a class=\"t\" href=\"glosario.html#duhkha\" data-t=\"duhkha\">dolor</a>, se llama <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>. Ese yoga ha de practicarse con determinación, con el ánimo sin desfallecer.</span>", "palabras": [{"iast": "tam", "sa": "तम्", "gram": "ac. sg. m. pron.", "es": "eso, ése"}, {"iast": "vidyāt", "sa": "विद्यात्", "gram": "3 sg. opt. act.", "es": "sépase", "analisis": "√vid (saber)"}, {"iast": "duḥkha-saṃyoga-viyogam", "sa": "दुःखसंयोगवियोगम्", "gram": "ac. sg. m. comp.", "es": "la desunión de la unión con el dolor", "ref": "duhkha", "analisis": "duḥkha (dolor) + saṃyoga (unión, contacto) + viyoga (separación, desunión); los dos últimos, de √yuj, la raíz de *yoga*"}, {"iast": "yoga-saṃjñitam", "sa": "योगसंज्ञितम्", "gram": "ac. sg. m. comp.", "es": "llamado yoga", "ref": "yoga", "analisis": "yoga + saṃjñita (denominado), de saṃjñā (nombre)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ese"}, {"iast": "niścayena", "sa": "निश्चयेन", "gram": "instr. sg. m.", "es": "con determinación", "analisis": "nis-√ci (decidir con firmeza)"}, {"iast": "yoktavyaḥ", "sa": "योक्तव्यः", "gram": "nom. sg. m. part. fut. pas.", "es": "ha de practicarse", "analisis": "√yuj"}, {"iast": "yogaḥ", "sa": "योगः", "gram": "nom. sg. m.", "es": "el yoga", "ref": "yoga"}, {"iast": "anirviṇṇa-cetasā", "sa": "अनिर्विण्णचेतसा", "gram": "instr. sg. m. comp.", "es": "con el ánimo sin desfallecer", "analisis": "a (no) + nirviṇṇa (abatido, hastiado), ppp de nir-√vid + cetas (ánimo, mente)"}], "nota": "<p>La frase empezada en <a class=\"vref\" href=\"capitulo-06.html#v20\" data-v=\"6.20\">6.20</a> se cierra con un juego de palabras: <em>saṃyoga</em> («unión»), <em>viyoga</em> («desunión») y <em>yoga</em> vienen de la misma raíz, √yuj, «uncir». El yoga, la «unión», se define como una desunión: la de nuestro vínculo con el dolor. La traducción conserva la paradoja. <em>Anirviṇṇa-cetas</em>: «de ánimo no abatido», sin el hastío que hace abandonar una práctica larga.</p>", "interp": [{"titulo": "Un nombre por contraste", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> subraya que a ese estado se le da el nombre de yoga «por lo contrario»: es una separación, y sin embargo se le llama unión. Y, concluida la descripción del fruto del yoga, la segunda mitad vuelve a mandar que se practique, para establecer dos medios: la resolución firme (<em>niścaya</em>) y el ánimo que no se abate.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El dolor y el yoga", "html": "<p>La definición pone en el centro el dolor (<em>duḥkha</em>), como lo harán después los <em>Yoga-sūtra</em>: «lo que hay que evitar es el dolor por venir» (2.16). Es un rasgo compartido por las disciplinas indias de liberación, el budismo incluido: la pregunta de partida no es qué es el mundo, sino cómo dejar de sufrir.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Sépase que a esa ruptura del vínculo con el dolor se la llama yoga. Ese yoga ha de practicarse con determinación, con el ánimo sin desfallecer.", "nota": "<p>Sin el juego de palabras: <em>saṃyoga</em> como «vínculo, contacto» y <em>viyoga</em> como «ruptura, separación». Se pierde la paradoja de que el «yoga» sea una «des-unión», pero la frase gana en claridad.</p>"}], "ens": "la-desunion-del-dolor"}, {"n": 24, "hablante": "krsna", "sa": ["सङ्कल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः ।", "मनसैवेन्द्रियग्रामं विनियम्य समन्ततः ॥२४॥"], "iast": ["saṅkalpa-prabhavān kāmāṃs tyaktvā sarvān aśeṣataḥ", "manasaivendriya-grāmaṃ viniyamya samantataḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Abandonando por completo todos los <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseos</a> que nacen de la <a class=\"t\" href=\"glosario.html#sankalpa\" data-t=\"sankalpa\">intención</a> y refrenando por todas partes, con la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> misma, el conjunto de los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a>,</span>", "palabras": [{"iast": "saṅkalpa-prabhavān", "sa": "सङ्कल्पप्रभवान्", "gram": "ac. pl. m. comp.", "es": "nacidos de la intención", "ref": "sankalpa", "analisis": "saṅkalpa (intención, propósito imaginado) + prabhava (origen)"}, {"iast": "kāmān", "sa": "कामान्", "gram": "ac. pl. m.", "es": "los deseos", "ref": "kama"}, {"iast": "tyaktvā", "sa": "त्यक्त्वा", "gram": "abs.", "es": "abandonando", "analisis": "√tyaj (dejar)"}, {"iast": "sarvān", "sa": "सर्वान्", "gram": "ac. pl. m.", "es": "todos"}, {"iast": "aśeṣataḥ", "sa": "अशेषतः", "gram": "ind.", "es": "por completo, sin resto", "analisis": "a (sin) + śeṣa (resto) + -tas"}, {"iast": "manasā", "sa": "मनसा", "gram": "instr. sg. n.", "es": "con la mente", "ref": "manas"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "sola, misma"}, {"iast": "indriya-grāmam", "sa": "इन्द्रियग्रामम्", "gram": "ac. sg. m. comp.", "es": "el conjunto de los sentidos", "ref": "indriya", "analisis": "indriya (sentido) + grāma (aldea, conjunto)"}, {"iast": "viniyamya", "sa": "विनियम्य", "gram": "abs.", "es": "refrenando", "analisis": "vi-ni-√yam"}, {"iast": "samantataḥ", "sa": "समन्ततः", "gram": "ind.", "es": "por todas partes"}], "nota": "<p><em>Saṅkalpa</em>: la intención o el propósito que la mente se forja; de él nacen los deseos; ya en <a class=\"vref\" href=\"capitulo-06.html#v2\" data-v=\"6.2\">6.2</a> Kṛṣṇa decía que no es yogui quien no ha renunciado a la intención. <em>Indriya-grāma</em>: literalmente «la aldea de los sentidos», su conjunto. <em>Manasā eva</em>: «con la mente misma», que es la que los conduce; el mismo instrumento que los suelta es el que los recoge. Esta frase continúa en el verso siguiente.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "traer-la-mente-de-vuelta"}, {"n": 25, "hablante": "krsna", "sa": ["शनैः शनैरुपरमेद्बुद्ध्या धृतिगृहीतया ।", "आत्मसंस्थं मनः कृत्वा न किञ्चिदपि चिन्तयेत् ॥२५॥"], "iast": ["śanaiḥ śanair uparamed buddhyā dhṛti-gṛhītayā", "ātma-saṃsthaṃ manaḥ kṛtvā na kiñcid api cintayet"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">que se aquiete poco a poco, con el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> sostenido por la firmeza; y, asentada la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> en el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>, que no piense en nada.</span>", "palabras": [{"iast": "śanaiḥ śanaiḥ", "sa": "शनैः शनैः", "gram": "ind.", "es": "poco a poco", "analisis": "śanais (despacio), repetido"}, {"iast": "uparamet", "sa": "उपरमेत्", "gram": "3 sg. opt.", "es": "que se aquiete, que se retire", "analisis": "upa-√ram (cesar, retirarse)"}, {"iast": "buddhyā", "sa": "बुद्ध्या", "gram": "instr. sg. f.", "es": "con el entendimiento", "ref": "buddhi"}, {"iast": "dhṛti-gṛhītayā", "sa": "धृतिगृहीतया", "gram": "instr. sg. f. comp.", "es": "sostenido por la firmeza", "analisis": "dhṛti (firmeza, constancia) + gṛhīta (tomado, sujeto), ppp de √grah"}, {"iast": "ātma-saṃstham", "sa": "आत्मसंस्थम्", "gram": "ac. sg. n. comp.", "es": "asentada en el sí-mismo", "ref": "atman", "analisis": "ātman + saṃstha (que reside, asentado)"}, {"iast": "manaḥ", "sa": "मनः", "gram": "ac. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "kṛtvā", "sa": "कृत्वा", "gram": "abs.", "es": "haciendo"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "kiñcit", "sa": "किञ्चित्", "gram": "ac. sg. n. pron. indef.", "es": "nada"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "en absoluto"}, {"iast": "cintayet", "sa": "चिन्तयेत्", "gram": "3 sg. opt. caus.", "es": "que piense", "analisis": "√cint (pensar)"}], "nota": "<p><em>Śanaiḥ śanaiḥ</em>: «despacio, despacio», con la repetición que en sánscrito indica gradación. <em>Uparamet</em>: «que cese, que se retire», el mismo verbo que en <a class=\"vref\" href=\"capitulo-06.html#v20\" data-v=\"6.20\">6.20</a> («se aquieta»). <em>Dhṛti</em>: «firmeza, constancia», la cualidad que mantiene el entendimiento en su sitio. <em>Na kiñcid api cintayet</em>: no se trata de pensar en el vacío, sino de no pensar en otra cosa que el sí-mismo en que la mente ya está asentada.</p>", "interp": [{"titulo": "La regla suprema del yoga", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica que, una vez la mente hecha estable en el sí-mismo, el yogui no debe pensar en nada, y llama a esto la instrucción suprema del yoga.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Despacio", "html": "<p>La Gītā, que en otros lugares pide decisión inmediata, aquí pide paciencia: el aquietamiento no se impone de golpe, sino «poco a poco». Con el verso anterior forman una secuencia práctica: dejar los deseos, recoger los sentidos con la mente, apoyar el entendimiento en la firmeza, asentar la mente en el sí-mismo y, sólo entonces, dejar de pensar en otra cosa.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "que se retire poco a poco de los objetos, con el entendimiento sostenido por la firmeza; y, asentada la mente en el sí-mismo, que no piense en nada.", "nota": "<p><em>Uparamet</em> puede entenderse sin complemento, «que se aquiete, que cese», como en la traducción principal, o como «que se retire, que se aparte», sobrentendiendo de qué: de los objetos de los sentidos que el verso anterior acaba de recoger.</p>"}], "ens": "traer-la-mente-de-vuelta"}, {"n": 26, "hablante": "krsna", "sa": ["यतो यतो निश्चरति मनश्चञ्चलमस्थिरम् ।", "ततस्ततो नियम्यैतदात्मन्येव वशं नयेत् ॥२६॥"], "iast": ["yato yato niścarati manaś cañcalam asthiram", "tatas tato niyamyaitad ātmany eva vaśaṃ nayet"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Cada vez que la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a>, inquieta e inestable, se escape, adondequiera que vaya, que la refrene desde allí y la devuelva al dominio del <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a> solo.</span>", "palabras": [{"iast": "yato yato", "sa": "यतो यतो", "gram": "ind.", "es": "adondequiera que, cada vez que", "analisis": "yatas (de donde, por lo cual), repetido: «por cualquier motivo, hacia cualquier lado»"}, {"iast": "niścarati", "sa": "निश्चरति", "gram": "3 sg. pres. act.", "es": "se escapa, sale", "analisis": "nis-√car (salir, vagar fuera)"}, {"iast": "manaḥ", "sa": "मनः", "gram": "nom. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "cañcalam", "sa": "चञ्चलम्", "gram": "nom. sg. n.", "es": "inquieta"}, {"iast": "asthiram", "sa": "अस्थिरम्", "gram": "nom. sg. n.", "es": "inestable", "analisis": "a (no) + sthira (firme)"}, {"iast": "tatas tato", "sa": "ततस्ततो", "gram": "ind.", "es": "desde allí, de cada uno de esos sitios"}, {"iast": "niyamya", "sa": "नियम्य", "gram": "abs.", "es": "refrenando", "analisis": "ni-√yam"}, {"iast": "etat", "sa": "एतत्", "gram": "ac. sg. n. pron.", "es": "esta (mente)"}, {"iast": "ātmani", "sa": "आत्मनि", "gram": "loc. sg. m.", "es": "en el sí-mismo", "ref": "atman"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "solo"}, {"iast": "vaśam", "sa": "वशम्", "gram": "ac. sg. m.", "es": "bajo dominio"}, {"iast": "nayet", "sa": "नयेत्", "gram": "3 sg. opt. act.", "es": "que lleve", "analisis": "√nī (conducir)"}], "nota": "<p><em>Yato yato… tatas tato</em>: «de donde quiera que… de allí mismo», la correlación repetida que indica que la operación se hace una y otra vez, cada vez que haga falta. <em>Cañcala</em> y <em>asthira</em>: «inquieta» e «inestable»; Arjuna usará la primera palabra en <a class=\"vref\" href=\"capitulo-06.html#v34\" data-v=\"6.34\">6.34</a> para decir que la mente es tan difícil de sujetar como el viento. <em>Vaśaṃ nayet</em>: «que la lleve bajo dominio»; «devolver» traduce el sentido de la repetición.</p>", "interp": [{"titulo": "Ver lo que atrae a la mente", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende <em>yato yato</em> como «por cualquier motivo», el sonido u otro objeto que arrastra a la mente; refrenarla desde allí es examinar la verdadera naturaleza de ese objeto hasta reducirlo a mera apariencia y cultivar el desapego, y así devolverla al sí-mismo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La meditación como retorno", "html": "<p>El verso no promete una mente que no se escape, sino un yogui que la trae de vuelta cada vez: la distracción no es el fracaso de la práctica, sino el momento en que se practica. Arjuna objetará enseguida que la mente es tan difícil de sujetar como el viento (<a class=\"vref\" href=\"capitulo-06.html#v34\" data-v=\"6.34\">6.34</a>), y Kṛṣṇa responderá con dos palabras: práctica y desapego (<a class=\"vref\" href=\"capitulo-06.html#v35\" data-v=\"6.35\">6.35</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "traer-la-mente-de-vuelta"}, {"n": 27, "hablante": "krsna", "sa": ["प्रशान्तमनसं ह्येनं योगिनं सुखमुत्तमम् ।", "उपैति शान्तरजसं ब्रह्मभूतमकल्मषम् ॥२७॥"], "iast": ["praśānta-manasaṃ hy enaṃ yoginaṃ sukham uttamam", "upaiti śānta-rajasaṃ brahma-bhūtam akalmaṣam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pues a ese <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> de <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> serena, en quien el <a class=\"t\" href=\"glosario.html#rajas\" data-t=\"rajas\">rajas</a> se ha calmado, convertido en <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> y sin impureza, le llega la <a class=\"t\" href=\"glosario.html#sukha\" data-t=\"sukha\">dicha</a> suprema.</span>", "palabras": [{"iast": "praśānta-manasam", "sa": "प्रशान्तमनसम्", "gram": "ac. sg. m. comp.", "es": "de mente serena", "ref": "manas", "analisis": "praśānta (calmado), ppp de pra-√śam + manas (mente)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a éste"}, {"iast": "yoginam", "sa": "योगिनम्", "gram": "ac. sg. m.", "es": "al yogui", "ref": "yogin"}, {"iast": "sukham", "sa": "सुखम्", "gram": "nom. sg. n.", "es": "la dicha", "ref": "sukha"}, {"iast": "uttamam", "sa": "उत्तमम्", "gram": "nom. sg. n.", "es": "suprema"}, {"iast": "upaiti", "sa": "उपैति", "gram": "3 sg. pres. act.", "es": "llega a", "analisis": "upa-√i (acercarse, llegar)"}, {"iast": "śānta-rajasam", "sa": "शान्तरजसम्", "gram": "ac. sg. m. comp.", "es": "en quien el rajas se ha calmado", "ref": "rajas", "analisis": "śānta (calmado) + rajas (la guṇa de la pasión y la agitación)"}, {"iast": "brahma-bhūtam", "sa": "ब्रह्मभूतम्", "gram": "ac. sg. m. comp.", "es": "convertido en brahman", "ref": "brahman", "analisis": "brahma (brahman) + bhūta (llegado a ser)"}, {"iast": "akalmaṣam", "sa": "अकल्मषम्", "gram": "ac. sg. m.", "es": "sin impureza", "analisis": "a (sin) + kalmaṣa (mancha, impureza)"}], "nota": "<p>La dicha es aquí sujeto: no la alcanza el yogui, sino que «llega a él» (<em>upaiti</em>). <em>Śānta-rajas</em>: el <a class=\"t\" href=\"glosario.html#rajas\" data-t=\"rajas\">rajas</a> es la guṇa de la actividad y el deseo, la que agita la mente; calmado, la mente queda en paz. <em>Brahma-bhūta</em>: «convertido en brahman», como en <a class=\"vref\" href=\"capitulo-05.html#v24\" data-v=\"5.24\">5.24</a>. <em>Akalmaṣa</em>: «sin impureza», como los videntes de <a class=\"vref\" href=\"capitulo-05.html#v25\" data-v=\"5.25\">5.25</a>.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-contacto-con-brahman"}, {"n": 28, "hablante": "krsna", "sa": ["युञ्जन्नेवं सदात्मानं योगी विगतकल्मषः ।", "सुखेन ब्रह्मसंस्पर्शमत्यन्तं सुखमश्नुते ॥२८॥"], "iast": ["yuñjann evaṃ sadātmānaṃ yogī vigata-kalmaṣaḥ", "sukhena brahma-saṃsparśam atyantaṃ sukham aśnute"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Ejercitándose así siempre en el yoga, el <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a>, libre de impurezas, goza sin esfuerzo de la <a class=\"t\" href=\"glosario.html#sukha\" data-t=\"sukha\">dicha</a> infinita del <a class=\"t\" href=\"glosario.html#sparsa\" data-t=\"sparsa\">contacto</a> con <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>.</span>", "palabras": [{"iast": "yuñjan", "sa": "युञ्जन्", "gram": "nom. sg. m. ppa", "es": "ejercitando (en yoga)", "analisis": "√yuj"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "sadā", "sa": "सदा", "gram": "ind.", "es": "siempre"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "ac. sg. m.", "es": "a sí mismo", "ref": "atman"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "el yogui", "ref": "yogin"}, {"iast": "vigata-kalmaṣaḥ", "sa": "विगतकल्मषः", "gram": "nom. sg. m. comp.", "es": "libre de impurezas", "analisis": "vigata (ido, desaparecido) + kalmaṣa (impureza)"}, {"iast": "sukhena", "sa": "सुखेन", "gram": "instr. sg. n.", "es": "fácilmente, con gozo", "ref": "sukha"}, {"iast": "brahma-saṃsparśam", "sa": "ब्रह्मसंस्पर्शम्", "gram": "ac. sg. n. comp.", "es": "del contacto con brahman", "ref": "sparsa", "analisis": "brahma (brahman) + saṃsparśa (contacto)"}, {"iast": "atyantam", "sa": "अत्यन्तम्", "gram": "ac. sg. n.", "es": "infinita, sin término", "analisis": "ati (más allá) + anta (fin)"}, {"iast": "sukham", "sa": "सुखम्", "gram": "ac. sg. n.", "es": "la dicha", "ref": "sukha"}, {"iast": "aśnute", "sa": "अश्नुते", "gram": "3 sg. pres. med.", "es": "goza, alcanza", "analisis": "√aś (alcanzar, obtener)"}], "nota": "<p><em>Yuñjann ātmānam</em>: «uniéndose a sí mismo (en yoga)», ejercitándose. <em>Sukhena</em>: el instrumental de <em>sukha</em> significa «con facilidad», aunque el oído oye también «con dicha»; el verso juega con la palabra, que aparece dos veces. <em>Brahma-saṃsparśa</em>: «el contacto con brahman». Responde a <a class=\"vref\" href=\"capitulo-05.html#v21\" data-v=\"5.21\">5.21</a>–<a class=\"vref\" href=\"capitulo-05.html#v22\" data-v=\"5.22\">5.22</a>: los goces nacidos del contacto con lo externo son fuentes de dolor; el contacto con brahman da una dicha <em>atyanta</em>, «sin fin».</p>", "interp": [{"titulo": "Dos contactos", "html": "<p>El capítulo 5 había enseñado a desconfiar del <a class=\"t\" href=\"glosario.html#sparsa\" data-t=\"sparsa\">contacto</a>: los goces «nacidos del contacto» tienen principio y fin. Aquí la misma palabra nombra la meta: el «contacto con brahman». La Gītā no opone contacto y retiro, sino dos objetos de contacto: lo que pasa y lo que no pasa. La dicha que se buscaba fuera, y que se agotaba, se encuentra en otro lugar, y no se agota.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-contacto-con-brahman"}, {"n": 29, "hablante": "krsna", "sa": ["सर्वभूतस्थमात्मानं सर्वभूतानि चात्मनि ।", "ईक्षते योगयुक्तात्मा सर्वत्र समदर्शनः ॥२९॥"], "iast": ["sarva-bhūta-stham ātmānaṃ sarva-bhūtāni cātmani", "īkṣate yoga-yuktātmā sarvatra sama-darśanaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El que está <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a> y ve en todas partes lo mismo ve el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a> presente en todos los seres, y a todos los seres en el sí-mismo.</span>", "palabras": [{"iast": "sarva-bhūta-stham", "sa": "सर्वभूतस्थम्", "gram": "ac. sg. m. comp.", "es": "presente en todos los seres", "analisis": "sarva (todo) + bhūta (ser) + stha (que está, de √sthā)"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "ac. sg. m.", "es": "el sí-mismo", "ref": "atman"}, {"iast": "sarva-bhūtāni", "sa": "सर्वभूतानि", "gram": "ac. pl. n. comp.", "es": "a todos los seres", "analisis": "sarva (todo) + bhūta (ser)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "ātmani", "sa": "आत्मनि", "gram": "loc. sg. m.", "es": "en el sí-mismo", "ref": "atman"}, {"iast": "īkṣate", "sa": "ईक्षते", "gram": "3 sg. pres. med.", "es": "ve", "analisis": "√īkṣ (mirar, ver)"}, {"iast": "yoga-yuktātmā", "sa": "योगयुक्तात्मा", "gram": "nom. sg. m. comp. (bahuvrīhi)", "es": "el que tiene el sí-mismo unido en yoga", "ref": "yukta", "analisis": "yoga + yukta (unido, de √yuj) + ātman (sí-mismo; aquí, la mente)"}, {"iast": "sarvatra", "sa": "सर्वत्र", "gram": "ind.", "es": "en todas partes"}, {"iast": "sama-darśanaḥ", "sa": "समदर्शनः", "gram": "nom. sg. m. comp. (bahuvrīhi)", "es": "que ve lo mismo", "ref": "samatva", "analisis": "sama (igual, lo mismo) + darśana (visión, de √dṛś)"}], "nota": "<p><em>Yoga-yuktātmā</em>: literalmente «el de sí-mismo unido en yoga»; <em>ātman</em> tiene aquí, como en otros compuestos del capítulo, el sentido de «mente» o «interior». <em>Sama-darśana</em>, «el que ve lo mismo», recoge el <em>sama-darśin</em> de <a class=\"vref\" href=\"capitulo-05.html#v18\" data-v=\"5.18\">5.18</a>. El verso tiene dos direcciones: el sí-mismo en todos los seres y todos los seres en el sí-mismo; el siguiente las repite referidas a Kṛṣṇa («me ve en todas partes y ve todo en mí»), como ya había hecho <a class=\"vref\" href=\"capitulo-04.html#v35\" data-v=\"4.35\">4.35</a>.</p>", "interp": [{"titulo": "Un solo sí-mismo en todos", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo lee como la visión de la identidad: el yogui ve que su propio sí-mismo es el de todos los seres, desde Brahmā hasta una brizna de hierba, y que todos ellos son uno con él; «ve lo mismo» porque ve en todas partes el único brahman.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Sí-mismos iguales", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende que el yogui ve su sí-mismo igual al de los demás seres: separados de la <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a>, todos los sí-mismos tienen la misma forma, la del conocimiento, como ya había dicho a propósito de <a class=\"vref\" href=\"capitulo-04.html#v35\" data-v=\"4.35\">4.35</a> y <a class=\"vref\" href=\"capitulo-05.html#v18\" data-v=\"5.18\">5.18</a>. Lo que se ve es la igualdad, no la identidad.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-si-mismo-en-todos-los-seres"}, {"n": 30, "hablante": "krsna", "sa": ["यो मां पश्यति सर्वत्र सर्वं च मयि पश्यति ।", "तस्याहं न प्रणश्यामि स च मे न प्रणश्यति ॥३०॥"], "iast": ["yo māṃ paśyati sarvatra sarvaṃ ca mayi paśyati", "tasyāhaṃ na praṇaśyāmi sa ca me na praṇaśyati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien me ve en todas partes y ve todo en mí, para él yo no me pierdo, y él no se pierde para mí.</span>", "palabras": [{"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "paśyati", "sa": "पश्यति", "gram": "3 sg. pres. act.", "es": "ve", "analisis": "√dṛś / paś (ver)"}, {"iast": "sarvatra", "sa": "सर्वत्र", "gram": "ind.", "es": "en todas partes"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "ac. sg. n.", "es": "todo"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg.", "es": "en mí"}, {"iast": "paśyati", "sa": "पश्यति", "gram": "3 sg. pres. act.", "es": "ve"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. m.", "es": "para él"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "praṇaśyāmi", "sa": "प्रणश्यामि", "gram": "1 sg. pres. act.", "es": "me pierdo", "analisis": "pra + √naś (perderse, desaparecer)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m.", "es": "él"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "me", "sa": "मे", "gram": "gen. sg.", "es": "para mí"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "praṇaśyati", "sa": "प्रणश्यति", "gram": "3 sg. pres. act.", "es": "se pierde", "analisis": "pra + √naś"}], "nota": "<p><em>Praṇaś</em> es «perderse, desaparecer»; aplicado a la vista, «perderse de vista». La frase es recíproca: Kṛṣṇa nunca deja de estar presente para quien lo ve en todo, y quien lo ve así nunca queda fuera de su alcance. En <a class=\"vref\" href=\"capitulo-09.html#v31\" data-v=\"9.31\">9.31</a> Kṛṣṇa dirá algo cercano: «mi devoto no se pierde» (<em>na me bhaktaḥ praṇaśyati</em>).</p>", "interp": [{"titulo": "No hay distancia", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, Kṛṣṇa no «se pierde» para el sabio, es decir, no se le vuelve invisible o lejano, porque el sí-mismo del sabio y el Señor son uno: lo que es el propio sí-mismo no puede quedar fuera de la vista.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Del sí-mismo al Señor", "html": "<p>El paso de <a class=\"vref\" href=\"capitulo-06.html#v29\" data-v=\"6.29\">6.29</a> a este verso es característico de la Gītā: la visión del sí-mismo en todos los seres, que podría quedarse en una experiencia impersonal, se convierte en la visión de Kṛṣṇa en todo. Los versos siguientes llevan esa visión a la adoración (<a class=\"vref\" href=\"capitulo-06.html#v31\" data-v=\"6.31\">6.31</a>) y el capítulo terminará declarando superior al yogui que lo adora con fe (<a class=\"vref\" href=\"capitulo-06.html#v47\" data-v=\"6.47\">6.47</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-si-mismo-en-todos-los-seres"}, {"n": 31, "hablante": "krsna", "sa": ["सर्वभूतस्थितं यो मां भजत्येकत्वमास्थितः ।", "सर्वथा वर्तमानोऽपि स योगी मयि वर्तते ॥३१॥"], "iast": ["sarva-bhūta-sthitaṃ yo māṃ bhajaty ekatvam āsthitaḥ", "sarvathā vartamāno 'pi sa yogī mayi vartate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien, establecido en la unidad, me <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">adora</a> como presente en todos los seres, ese <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a>, viva como viva, vive en mí.</span>", "palabras": [{"iast": "sarva-bhūta-sthitam", "sa": "सर्वभूतस्थितम्", "gram": "ac. sg. m. comp.", "es": "presente en todos los seres", "analisis": "sarva (todo) + bhūta (ser) + sthita (que está, de √sthā)"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "bhajati", "sa": "भजति", "gram": "3 sg. pres. act.", "es": "adora", "ref": "bhakti", "analisis": "√bhaj (participar, servir, adorar), de donde bhakti"}, {"iast": "ekatvam", "sa": "एकत्वम्", "gram": "ac. sg. n.", "es": "la unidad", "analisis": "eka (uno) + -tva (abstracto)"}, {"iast": "āsthitaḥ", "sa": "आस्थितः", "gram": "nom. sg. m. part.", "es": "establecido en", "analisis": "ā + √sthā (estar, asentarse)"}, {"iast": "sarvathā", "sa": "सर्वथा", "gram": "ind.", "es": "de cualquier modo"}, {"iast": "vartamānaḥ", "sa": "वर्तमानः", "gram": "nom. sg. m. part. pres. med.", "es": "viviendo", "analisis": "√vṛt (estar, conducirse, vivir)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aunque"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m.", "es": "ese"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "yogui", "ref": "yogin", "analisis": "yogin"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg.", "es": "en mí"}, {"iast": "vartate", "sa": "वर्तते", "gram": "3 sg. pres. med.", "es": "vive", "analisis": "√vṛt"}], "nota": "<p><em>Bhajati</em>, de √bhaj, el verbo del que viene <em>bhakti</em>: «participa de», «sirve», «adora». Es la primera vez que el capítulo de la meditación habla de adorar a Kṛṣṇa. <em>Sarvathā vartamāno &#x27;pi</em>, «aunque viva de cualquier modo», es decir, cualquiera que sea su condición o su conducta exterior; no se trata de una licencia, sino de que su estado no depende de las circunstancias.</p>", "interp": [{"titulo": "Liberado en cualquier condición", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lee la primera mitad del verso como una repetición de la visión de la unidad del sí-mismo de los versos anteriores, en la que el yogui y el Señor, presente en todos los seres como su sí-mismo, son uno; y la segunda, como su fruto, la liberación: viva como viva, ese yogui permanece en el estado supremo de Viṣṇu, liberado para siempre, y nada le impide la liberación.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La devoción dentro de la meditación", "html": "<p>El verbo <em>bhaj</em> anticipa el desenlace del capítulo: entre todos los yoguis, el más unido es el que adora a Kṛṣṇa con fe (<a class=\"vref\" href=\"capitulo-06.html#v47\" data-v=\"6.47\">6.47</a>). La Gītā no separa la meditación de la <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoción</a>; la una desemboca en la otra, y los capítulos siguientes (<a class=\"vref\" href=\"capitulo-07.html#v1\" data-v=\"7.1\">7.1</a>) seguirán ese camino.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Quien me adora como el uno presente en todos los seres, ese yogui, viva como viva, vive en mí.", "nota": "<p><em>Ekatvam āsthitaḥ</em>, «establecido en la unidad», no dice de qué unidad se trata. Puede ser la del yogui con Kṛṣṇa, que es la lectura de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y de <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> (y la «no diferencia» de <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>), o la de Kṛṣṇa mismo, que permanece uno aunque esté en todos los seres: <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> lo entiende como «establecido en que el Señor es uno solo en todas partes». <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> la entiende como la igualdad de forma, la del conocimiento, entre el sí-mismo del yogui y el Señor. Esta alternativa hace explícita la segunda lectura.</p>"}], "ens": "el-si-mismo-en-todos-los-seres"}, {"n": 32, "hablante": "krsna", "sa": ["आत्मौपम्येन सर्वत्र समं पश्यति योऽर्जुन ।", "सुखं वा यदि वा दुःखं स योगी परमो मतः ॥३२॥"], "iast": ["ātmaupamyena sarvatra samaṃ paśyati yo 'rjuna", "sukhaṃ vā yadi vā duḥkhaṃ sa yogī paramo mataḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien, por analogía consigo mismo, ve igual en todas partes el <a class=\"t\" href=\"glosario.html#sukha\" data-t=\"sukha\">placer</a> o el <a class=\"t\" href=\"glosario.html#duhkha\" data-t=\"duhkha\">dolor</a>, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>, ese <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> es tenido por el más alto.</span>", "palabras": [{"iast": "ātmaupamyena", "sa": "आत्मौपम्येन", "gram": "ins. sg. n. comp.", "es": "por analogía consigo mismo", "analisis": "ātman (uno mismo) + aupamya (semejanza, comparación; de upamā «comparación»)"}, {"iast": "sarvatra", "sa": "सर्वत्र", "gram": "ind.", "es": "en todas partes"}, {"iast": "samam", "sa": "समम्", "gram": "ac. sg. n.", "es": "igual", "ref": "samatva"}, {"iast": "paśyati", "sa": "पश्यति", "gram": "3 sg. pres. act.", "es": "ve"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "sukham", "sa": "सुखम्", "gram": "ac. sg. n.", "es": "el placer", "ref": "sukha"}, {"iast": "vā", "sa": "वा", "gram": "ind.", "es": "o"}, {"iast": "yadi vā", "sa": "यदि वा", "gram": "ind.", "es": "o bien"}, {"iast": "duḥkham", "sa": "दुःखम्", "gram": "ac. sg. n.", "es": "el dolor", "ref": "duhkha"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m.", "es": "ese"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "yogui", "ref": "yogin"}, {"iast": "paramaḥ", "sa": "परमः", "gram": "nom. sg. m.", "es": "supremo"}, {"iast": "mataḥ", "sa": "मतः", "gram": "nom. sg. m. part.", "es": "es tenido por", "analisis": "√man (pensar, considerar)"}], "nota": "<p><em>Ātmaupamya</em> es «la comparación con uno mismo»: tomarse como medida para juzgar a los demás. La traducción conserva la ambigüedad del original, que admite dos desarrollos (véanse las alternativas): sentir el placer y el dolor ajenos como propios, o ver que el placer y el dolor no alcanzan a ningún sí-mismo. La primera es una regla moral, la segunda una forma de ecuanimidad; las dos acaban en una mirada igual sobre todos.</p>", "interp": [{"titulo": "No hacer a otro lo que duele a uno", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica la analogía así: como el placer es grato y el dolor ingrato para mí, así lo son para todos los seres. Quien lo ve no causa dolor a nadie y es, por eso, no-violento (<a class=\"t\" href=\"glosario.html#ahimsa\" data-t=\"ahimsa\">ahiṃsā</a>); ese yogui, firme en la visión correcta, es el más alto.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Una regla de oro", "html": "<p>Leída en clave ética, la «analogía consigo mismo» es la forma india de la regla de oro, que el <a class=\"t\" href=\"glosario.html#mahabharata\" data-t=\"mahabharata\">Mahābhārata</a> formula en varios lugares: «no hacer a otro lo que a uno le resulta desagradable; ése es, en resumen, el dharma» (Anuśāsana-parvan 13.114.8 en la edición crítica; casi igual en 5.39.57). El verso siguiente de ese pasaje usa la misma palabra que la Gītā, <em>ātmaupamya</em>, aplicada al placer y al dolor (13.114.9). Aquí no se presenta como un precepto, sino como el fruto de la meditación: quien ve el mismo sí-mismo en todos (<a class=\"vref\" href=\"capitulo-06.html#v29\" data-v=\"6.29\">6.29</a>) siente con todos.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Quien, tomándose a sí mismo como medida, siente como propios el placer y el dolor de todos los seres, oh Arjuna, ese yogui es tenido por el más alto.", "nota": "<p>Lectura ética de <em>ātmaupamya</em>: como a mí me agrada el placer y me hiere el dolor, así a todos; quien lo ve no hace daño a nadie. Es la lectura más extendida: la de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, que la desarrolla como no-violencia, y también la de <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>.</p>"}, {"html": "Quien, sabiendo que los sí-mismos de todos son semejantes al suyo, ve en todas partes con la misma mirada el placer o el dolor, oh Arjuna, ese yogui es tenido por el más alto.", "nota": "<p>Lectura contemplativa: la semejanza (<em>aupamya</em>) es la de los sí-mismos entre sí, y lo que se ve igual es que ni el placer ni el dolor tocan al sí-mismo, ni al propio ni al ajeno. Es la línea de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, que lee los versos 29–32 como grados de la visión de la igualdad.</p>"}], "ens": "el-si-mismo-en-todos-los-seres"}, {"n": 33, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "योऽयं योगस्त्वया प्रोक्तः साम्येन मधुसूदन ।", "एतस्याहं न पश्यामि चञ्चलत्वात्स्थितिं स्थिराम् ॥३३॥"], "iast": ["arjuna uvāca", "yo 'yaṃ yogas tvayā proktaḥ sāmyena madhusūdana", "etasyāhaṃ na paśyāmi cañcalatvāt sthitiṃ sthirām"], "rojas": [], "t": "<span class=\"vt-parte\">Este yoga de la igualdad que me has enseñado, oh <a class=\"t\" href=\"glosario.html#madhusudana\" data-t=\"madhusudana\">Madhusūdana</a>, no veo cómo pueda mantenerse firme, por la inquietud de la mente.</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "el que"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m.", "es": "este"}, {"iast": "yogaḥ", "sa": "योगः", "gram": "nom. sg. m.", "es": "yoga", "ref": "yoga"}, {"iast": "tvayā", "sa": "त्वया", "gram": "ins. sg.", "es": "por ti"}, {"iast": "proktaḥ", "sa": "प्रोक्तः", "gram": "nom. sg. m. part.", "es": "enseñado", "analisis": "pra + √vac (declarar, enseñar)"}, {"iast": "sāmyena", "sa": "साम्येन", "gram": "ins. sg. n.", "es": "como igualdad", "ref": "samatva", "analisis": "sāmya (igualdad, de sama «igual»)"}, {"iast": "madhusūdana", "sa": "मधुसूदन", "gram": "voc. sg. m.", "es": "oh Madhusūdana", "ref": "madhusudana"}, {"iast": "etasya", "sa": "एतस्य", "gram": "gen. sg. m.", "es": "de este"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "paśyāmi", "sa": "पश्यामि", "gram": "1 sg. pres. act.", "es": "veo"}, {"iast": "cañcalatvāt", "sa": "चञ्चलत्वात्", "gram": "abl. sg. n.", "es": "por la inquietud", "analisis": "cañcala (inquieto, que se mueve sin parar) + -tva (abstracto)"}, {"iast": "sthitim", "sa": "स्थितिम्", "gram": "ac. sg. f.", "es": "asiento, permanencia", "analisis": "sthiti (estado, permanencia, de √sthā)"}, {"iast": "sthirām", "sa": "स्थिराम्", "gram": "ac. sg. f.", "es": "estable", "analisis": "sthira (firme, estable)"}], "nota": "<p><em>Sāmyena</em>, «como igualdad» o «por la igualdad»: Arjuna resume con una palabra lo enseñado desde <a class=\"vref\" href=\"capitulo-06.html#v29\" data-v=\"6.29\">6.29</a>, la mirada igual sobre todos. <em>Cañcalatvāt</em>, «por la inquietud», no dice de qué; la traducción añade «de la mente», que el verso siguiente hace explícito. Es la primera intervención de Arjuna desde <a class=\"vref\" href=\"capitulo-05.html#v1\" data-v=\"5.1\">5.1</a>: la objeción no es teórica, sino práctica.</p>", "interp": [{"titulo": "La objeción del practicante", "html": "<p>Arjuna no discute la doctrina; duda de que sea posible vivirla. Es la objeción de cualquiera que haya intentado meditar, y la Gītā la toma en serio: Kṛṣṇa no la niega, sino que la concede y responde con un método (<a class=\"vref\" href=\"capitulo-06.html#v35\" data-v=\"6.35\">6.35</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 34, "hablante": "arjuna", "sa": ["चञ्चलं हि मनः कृष्ण प्रमाथि बलवद्दृढम् ।", "तस्याहं निग्रहं मन्ये वायोरिव सुदुष्करम् ॥३४॥"], "iast": ["cañcalaṃ hi manaḥ kṛṣṇa pramāthi balavad dṛḍham", "tasyāhaṃ nigrahaṃ manye vāyor iva su-duṣkaram"], "rojas": [], "t": "<span class=\"vt-parte\">Porque la mente es inquieta, oh <a class=\"t\" href=\"glosario.html#krsna\" data-t=\"krsna\">Kṛṣṇa</a>, turbulenta, poderosa y obstinada; dominarla me parece tan difícil como dominar el viento.</span>", "palabras": [{"iast": "cañcalam", "sa": "चञ्चलम्", "gram": "nom. sg. n.", "es": "inquieta"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque"}, {"iast": "manaḥ", "sa": "मनः", "gram": "nom. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "kṛṣṇa", "sa": "कृष्ण", "gram": "voc. sg. m.", "es": "oh Kṛṣṇa", "ref": "krsna"}, {"iast": "pramāthi", "sa": "प्रमाथि", "gram": "nom. sg. n.", "es": "turbulenta, que todo lo agita", "analisis": "pra + √math (agitar, batir; como se bate la leche)"}, {"iast": "balavat", "sa": "बलवत्", "gram": "nom. sg. n.", "es": "poderosa", "analisis": "bala (fuerza) + -vat (que tiene)"}, {"iast": "dṛḍham", "sa": "दृढम्", "gram": "nom. sg. n.", "es": "obstinada, tenaz", "analisis": "dṛḍha (firme, duro; de √dṛh «afirmar»)"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. n.", "es": "de ella"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "nigraham", "sa": "निग्रहम्", "gram": "ac. sg. m.", "es": "el dominio", "analisis": "ni + √grah (sujetar, refrenar)"}, {"iast": "manye", "sa": "मन्ये", "gram": "1 sg. pres. med.", "es": "considero", "analisis": "√man (pensar)"}, {"iast": "vāyoḥ", "sa": "वायोः", "gram": "gen. sg. m.", "es": "del viento", "analisis": "vāyu (viento, aire)"}, {"iast": "iva", "sa": "इव", "gram": "ind.", "es": "como"}, {"iast": "su-duṣkaram", "sa": "सुदुष्करम्", "gram": "ac. sg. m.", "es": "muy difícil", "analisis": "su (muy) + duṣkara (difícil de hacer, de dus + √kṛ)"}], "nota": "<p>Cuatro adjetivos para la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a>: <em>cañcala</em>, «inquieta», que no se queda quieta; <em>pramāthin</em>, «que lo agita todo», el mismo adjetivo que <a class=\"vref\" href=\"capitulo-02.html#v60\" data-v=\"2.60\">2.60</a> aplica a los sentidos, que «arrastran a la fuerza la mente»; <em>balavat</em>, «poderosa», y <em>dṛḍha</em>, «dura, tenaz», que no cede. La imagen del viento es exacta: no se lo puede atrapar ni encerrar.</p>", "interp": [{"titulo": "«Kṛṣṇa», el que arranca", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> se detiene en el vocativo: explica el nombre <em>Kṛṣṇa</em> por la raíz √kṛṣ, «arrastrar, arrancar», porque arranca los pecados y demás defectos de sus devotos. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> saca la consecuencia: al llamarlo así, Arjuna da a entender que sólo él puede arrancar también la inquietud de la mente.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 35, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "असंशयं महाबाहो मनो दुर्निग्रहं चलम् ।", "अभ्यासेन तु कौन्तेय वैराग्येण च गृह्यते ॥३५॥"], "iast": ["śrī-bhagavān uvāca", "asaṃśayaṃ mahā-bāho mano durnigrahaṃ calam", "abhyāsena tu kaunteya vairāgyeṇa ca gṛhyate"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Sin duda, oh <a class=\"t\" href=\"glosario.html#mahabaho\" data-t=\"mahabaho\">Mahābāhu</a>, la mente es inquieta y difícil de dominar; pero se la sujeta, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, con la <a class=\"t\" href=\"glosario.html#abhyasa\" data-t=\"abhyasa\">práctica</a> y el <a class=\"t\" href=\"glosario.html#vairagya\" data-t=\"vairagya\">desapego</a>.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria) + bhagavat (el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "asaṃśayam", "sa": "असंशयम्", "gram": "ind.", "es": "sin duda", "ref": "samsaya", "analisis": "a (no) + saṃśaya (duda)"}, {"iast": "mahā-bāho", "sa": "महाबाहो", "gram": "voc. sg. m. comp.", "es": "oh Mahābāhu", "ref": "mahabaho", "analisis": "mahā (grande) + bāhu (brazo)"}, {"iast": "manaḥ", "sa": "मनः", "gram": "nom. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "durnigraham", "sa": "दुर्निग्रहम्", "gram": "nom. sg. n.", "es": "difícil de dominar", "analisis": "dus (difícil) + nigraha (dominio)"}, {"iast": "calam", "sa": "चलम्", "gram": "nom. sg. n.", "es": "inquieta, móvil", "analisis": "cala (que se mueve, de √cal)"}, {"iast": "abhyāsena", "sa": "अभ्यासेन", "gram": "ins. sg. m.", "es": "con la práctica", "ref": "abhyasa", "analisis": "abhi + √as (aplicarse repetidamente)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh Kaunteya", "ref": "kaunteya"}, {"iast": "vairāgyeṇa", "sa": "वैराग्येण", "gram": "ins. sg. n.", "es": "con el desapego", "ref": "vairagya", "analisis": "vairāgya, de vi-rāga (sin pasión)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "gṛhyate", "sa": "गृह्यते", "gram": "3 sg. pres. pas.", "es": "se la sujeta", "analisis": "√grah (agarrar, sujetar)"}], "nota": "<p>Kṛṣṇa concede la objeción entera («sin duda») antes de responder. <em>Abhyāsa</em> es la práctica repetida, el volver una y otra vez; <em>vairāgya</em>, el desapego, literalmente «la ausencia de pasión» (véanse las fichas). Los dos términos, juntos, son también los de los <em>Yoga-sūtra</em> de Patañjali, que hacen de ellos el medio para aquietar la mente (1.12): «su detención se logra con la práctica y el desapego».</p>", "interp": [{"titulo": "Repetir y ver el defecto", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> define la práctica como la repetición de una misma idea sobre el objeto de meditación, y el desapego como la falta de sed por los goces, visibles o invisibles, que nace de ver una y otra vez sus defectos. Con esos dos medios se sujeta el movimiento de la mente.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Gītā y Yoga-sūtra", "html": "<p>La pareja <em>abhyāsa</em>–<em>vairāgya</em> reaparece en los <em>Yoga-sūtra</em> (1.12–1.16), que definen la práctica como el esfuerzo por mantenerse en la quietud, sostenido largo tiempo, sin interrupción y con devoción, y el desapego como el dominio de quien ya no siente sed por los objetos vistos u oídos. Que la Gītā y los <em>Yoga-sūtra</em> coincidan en los términos indica un vocabulario común del yoga; la datación relativa de los dos textos es discutida.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "practica-y-desapego"}, {"n": 36, "hablante": "krsna", "sa": ["असंयतात्मना योगो दुष्प्राप इति मे मतिः ।", "वश्यात्मना तु यतता शक्योऽवाप्तुमुपायतः ॥३६॥"], "iast": ["asaṃyatātmanā yogo duṣprāpa iti me matiḥ", "vaśyātmanā tu yatatā śakyo 'vāptum upāyataḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Para quien no se domina, el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> es difícil de alcanzar: así lo pienso; pero quien se ha hecho dueño de sí y se esfuerza puede alcanzarlo con los medios adecuados.</span>", "palabras": [{"iast": "asaṃyatātmanā", "sa": "असंयतात्मना", "gram": "ins. sg. m. comp. (bahuvrīhi)", "es": "para quien no se domina", "analisis": "a (no) + saṃyata (dominado, de sam-√yam) + ātman (uno mismo; la mente)"}, {"iast": "yogaḥ", "sa": "योगः", "gram": "nom. sg. m.", "es": "el yoga", "ref": "yoga"}, {"iast": "duṣprāpaḥ", "sa": "दुष्प्रापः", "gram": "nom. sg. m.", "es": "difícil de alcanzar", "analisis": "dus (difícil) + prāpa (alcanzable, de pra-√āp)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así"}, {"iast": "me", "sa": "मे", "gram": "gen. sg.", "es": "mi"}, {"iast": "matiḥ", "sa": "मतिः", "gram": "nom. sg. f.", "es": "opinión", "analisis": "√man (pensar)"}, {"iast": "vaśyātmanā", "sa": "वश्यात्मना", "gram": "ins. sg. m. comp. (bahuvrīhi)", "es": "por quien se ha hecho dueño de sí", "analisis": "vaśya (sometido, obediente) + ātman (uno mismo; la mente)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "yatatā", "sa": "यतता", "gram": "ins. sg. m. part. pres.", "es": "que se esfuerza", "ref": "yati", "analisis": "√yat (esforzarse)"}, {"iast": "śakyaḥ", "sa": "शक्यः", "gram": "nom. sg. m.", "es": "es posible", "analisis": "√śak (poder)"}, {"iast": "avāptum", "sa": "अवाप्तुम्", "gram": "inf.", "es": "alcanzar", "analisis": "ava + √āp (obtener)"}, {"iast": "upāyataḥ", "sa": "उपायतः", "gram": "ind.", "es": "con los medios adecuados", "analisis": "upāya (medio, recurso; de upa-√i «acercarse») + -tas"}], "nota": "<p><em>Asaṃyatātman</em> y <em>vaśyātman</em> se oponen: «el de sí-mismo no dominado» y «el de sí-mismo sometido»; <em>ātman</em> vale aquí «la mente» o «uno mismo». <em>Upāyataḥ</em>, «por medio de los recursos», remite a lo que acaba de decirse: la práctica y el desapego. El verso equilibra la concesión del anterior: el yoga es difícil, no imposible.</p>", "interp": [{"titulo": "Los medios ya dichos", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende los «medios» (<em>upāya</em>) como los que se acaban de enseñar, la práctica y el desapego: con ellos, quien ha sometido la mente y persevera puede alcanzar el yoga.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "practica-y-desapego"}, {"n": 37, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "अयतिः श्रद्धयोपेतो योगाच्चलितमानसः ।", "अप्राप्य योगसंसिद्धिं कां गतिं कृष्ण गच्छति ॥३७॥"], "iast": ["arjuna uvāca", "ayatiḥ śraddhayopeto yogāc calita-mānasaḥ", "aprāpya yoga-saṃsiddhiṃ kāṃ gatiṃ kṛṣṇa gacchati"], "rojas": [], "t": "<span class=\"vt-parte\">El que tiene <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a> pero <a class=\"t\" href=\"glosario.html#yati\" data-t=\"yati\">no persevera</a>, y cuya mente se aparta del <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>, ¿qué destino alcanza, oh <a class=\"t\" href=\"glosario.html#krsna\" data-t=\"krsna\">Kṛṣṇa</a>, si no llega a la perfección del yoga?</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "ayatiḥ", "sa": "अयतिः", "gram": "nom. sg. m.", "es": "el que no persevera", "ref": "yati", "analisis": "a (no) + yati (el que se esfuerza, de √yat)"}, {"iast": "śraddhayā", "sa": "श्रद्धया", "gram": "instr. sg. f.", "es": "con fe", "ref": "sraddha"}, {"iast": "upetaḥ", "sa": "उपेतः", "gram": "nom. sg. m. ppp", "es": "provisto", "analisis": "upa-√i (acercarse): «provisto de»"}, {"iast": "yogāt", "sa": "योगात्", "gram": "abl. sg. m.", "es": "del yoga", "ref": "yoga"}, {"iast": "calita-mānasaḥ", "sa": "चलितमानसः", "gram": "nom. sg. m. comp.", "es": "cuya mente se ha apartado", "ref": "manas", "analisis": "calita (movido, apartado; √cal) + mānasa (mente)"}, {"iast": "aprāpya", "sa": "अप्राप्य", "gram": "abs.", "es": "sin alcanzar", "analisis": "a (no) + pra-√āp (alcanzar)"}, {"iast": "yoga-saṃsiddhim", "sa": "योगसंसिद्धिम्", "gram": "ac. sg. f. comp.", "es": "la perfección del yoga", "analisis": "yoga + saṃsiddhi (perfección, logro pleno; sam-√sidh)"}, {"iast": "kām", "sa": "काम्", "gram": "ac. sg. f. pron.", "es": "qué"}, {"iast": "gatim", "sa": "गतिम्", "gram": "ac. sg. f.", "es": "destino", "analisis": "√gam (ir): «camino, destino»"}, {"iast": "kṛṣṇa", "sa": "कृष्ण", "gram": "voc. sg. m.", "es": "oh Kṛṣṇa", "ref": "krsna"}, {"iast": "gacchati", "sa": "गच्छति", "gram": "3 sg. pres. act.", "es": "alcanza, va", "analisis": "√gam (ir)"}], "nota": "<p><em>Ayati</em>: literalmente «el que no se esfuerza» (de √<em>yat</em>, como <a class=\"t\" href=\"glosario.html#yati\" data-t=\"yati\">yati</a>); no el que carece de fe, sino el que la tiene pero no persevera en la disciplina. Arjuna saca la consecuencia de su objeción de <a class=\"vref\" href=\"capitulo-06.html#v33\" data-v=\"6.33\">6.33</a>–<a class=\"vref\" href=\"capitulo-06.html#v34\" data-v=\"6.34\">6.34</a>: si la mente es tan inquieta, muchos no llegarán a la meta. <em>Gati</em>: «camino» y, de ahí, el destino que espera a cada uno después de la muerte.</p>", "interp": [{"titulo": "La pregunta del principiante", "html": "<p>Kṛṣṇa acaba de admitir que la mente es difícil de sujetar y que se logra con práctica y desapego (<a class=\"vref\" href=\"capitulo-06.html#v35\" data-v=\"6.35\">6.35</a>–<a class=\"vref\" href=\"capitulo-06.html#v36\" data-v=\"6.36\">6.36</a>). Arjuna no pregunta ya por el yogui consumado, sino por el que lo intenta y no lo consigue: la pregunta de cualquiera que empieza un camino largo sin saber si lo terminará.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 38, "hablante": "arjuna", "sa": ["कच्चिन्नोभयविभ्रष्टश्छिन्नाभ्रमिव नश्यति ।", "अप्रतिष्ठो महाबाहो विमूढो ब्रह्मणः पथि ॥३८॥"], "iast": ["kaccin nobhaya-vibhraṣṭaś chinnābhram iva naśyati", "apratiṣṭho mahā-bāho vimūḍho brahmaṇaḥ pathi"], "rojas": [], "t": "<span class=\"vt-parte\">¿No se pierde, caído de uno y otro lado, como una nube deshecha, sin apoyo, oh <a class=\"t\" href=\"glosario.html#mahabaho\" data-t=\"mahabaho\">Mahābāhu</a>, extraviado en el camino de <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>?</span>", "palabras": [{"iast": "kaccit", "sa": "कच्चित्", "gram": "ind.", "es": "acaso", "analisis": "partícula interrogativa que espera respuesta: «¿acaso…?»"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ubhaya-vibhraṣṭaḥ", "sa": "उभयविभ्रष्टः", "gram": "nom. sg. m. comp.", "es": "caído de uno y otro lado", "analisis": "ubhaya (ambos) + vibhraṣṭa (caído, apartado; vi-√bhraṃś)"}, {"iast": "chinna-abhram", "sa": "छिन्नाभ्रम्", "gram": "nom. sg. n. comp.", "es": "una nube deshecha", "analisis": "chinna (cortado, rasgado; √chid) + abhra (nube)"}, {"iast": "iva", "sa": "इव", "gram": "ind.", "es": "como"}, {"iast": "naśyati", "sa": "नश्यति", "gram": "3 sg. pres. act.", "es": "se pierde", "analisis": "√naś (perecer, perderse)"}, {"iast": "apratiṣṭhaḥ", "sa": "अप्रतिष्ठः", "gram": "nom. sg. m. adj.", "es": "sin apoyo", "analisis": "a (no) + pratiṣṭhā (apoyo, fundamento)"}, {"iast": "mahā-bāho", "sa": "महाबाहो", "gram": "voc. sg. m. comp.", "es": "oh Mahābāhu", "ref": "mahabaho"}, {"iast": "vimūḍhaḥ", "sa": "विमूढः", "gram": "nom. sg. m. ppp", "es": "extraviado", "ref": "moha", "analisis": "vi-√muh (extraviarse)"}, {"iast": "brahmaṇaḥ", "sa": "ब्रह्मणः", "gram": "gen. sg. n.", "es": "de brahman", "ref": "brahman"}, {"iast": "pathi", "sa": "पथि", "gram": "loc. sg. m.", "es": "en el camino", "analisis": "pathin (camino)"}], "nota": "<p>La imagen, tal como la explican <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, es la de una nube que se ha separado de una masa de nubes y se deshace en el aire antes de unirse a otra; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> añade que se pierde sin llegar a dar lluvia. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> cita la imagen sin explicarla. <em>Apratiṣṭha</em>: «sin apoyo, sin asiento firme». <em>Brahmaṇaḥ pathi</em>, «en el camino de brahman»: el camino que lleva a <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "¿No se pierde, privado de este mundo y del otro, como una nube deshecha, sin apoyo, oh Mahābāhu, extraviado en el camino de brahman?", "nota": "<p><em>Ubhaya-vibhraṣṭa</em>, «caído de ambos», no dice de qué. La traducción principal lo deja abierto. La alternativa sigue la respuesta de Kṛṣṇa, «ni en este mundo ni en el otro» (<a class=\"vref\" href=\"capitulo-06.html#v40\" data-v=\"6.40\">6.40</a>): el que dejó los bienes de este mundo por el yoga y no lo culminó se quedaría sin unos ni otro. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo entiende, en cambio, como caído del camino de las acciones y del camino del yoga.</p>"}]}, {"n": 39, "hablante": "arjuna", "sa": ["एतन्मे संशयं कृष्ण छेत्तुमर्हस्यशेषतः ।", "त्वदन्यः संशयस्यास्य छेत्ता न ह्युपपद्यते ॥३९॥"], "iast": ["etan me saṃśayaṃ kṛṣṇa chettum arhasy aśeṣataḥ", "tvad-anyaḥ saṃśayasyāsya chettā na hy upapadyate"], "rojas": [], "t": "<span class=\"vt-parte\">Te ruego, oh <a class=\"t\" href=\"glosario.html#krsna\" data-t=\"krsna\">Kṛṣṇa</a>, que cortes de raíz esta <a class=\"t\" href=\"glosario.html#samsaya\" data-t=\"samsaya\">duda</a> mía, pues fuera de ti no hay nadie que pueda cortarla.</span>", "palabras": [{"iast": "etat", "sa": "एतत्", "gram": "ac. sg. n. pron.", "es": "esta"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mía"}, {"iast": "saṃśayam", "sa": "संशयम्", "gram": "ac. sg. m.", "es": "duda", "ref": "samsaya"}, {"iast": "kṛṣṇa", "sa": "कृष्ण", "gram": "voc. sg. m.", "es": "oh Kṛṣṇa", "ref": "krsna"}, {"iast": "chettum", "sa": "छेत्तुम्", "gram": "inf.", "es": "cortar", "analisis": "√chid (cortar)"}, {"iast": "arhasi", "sa": "अर्हसि", "gram": "2 sg. pres. act.", "es": "debes, te ruego", "analisis": "√arh (merecer, deber)"}, {"iast": "aśeṣataḥ", "sa": "अशेषतः", "gram": "ind.", "es": "por completo", "analisis": "a (no) + śeṣa (resto): «sin dejar resto»"}, {"iast": "tvat-anyaḥ", "sa": "त्वदन्यः", "gram": "nom. sg. m. comp.", "es": "otro que tú", "analisis": "tvad (tú) + anya (otro)"}, {"iast": "saṃśayasya", "sa": "संशयस्य", "gram": "gen. sg. m.", "es": "de la duda", "ref": "samsaya"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. m. pron.", "es": "esta"}, {"iast": "chettā", "sa": "छेत्ता", "gram": "nom. sg. m.", "es": "el que corte", "analisis": "chettṛ, nombre de agente de √chid"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "upapadyate", "sa": "उपपद्यते", "gram": "3 sg. pres. med.", "es": "se halla, es posible", "analisis": "upa-√pad (llegar, ser adecuado)"}], "nota": "<p><em>Chettum</em>, «cortar»: la duda se corta, como en <a class=\"vref\" href=\"capitulo-04.html#v42\" data-v=\"4.42\">4.42</a>, donde Kṛṣṇa pedía cortarla con la espada del conocimiento; ahora es Arjuna quien le pide a él que la corte. <em>Aśeṣataḥ</em>: «sin dejar resto», de raíz.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 40, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "पार्थ नैवेह नामुत्र विनाशस्तस्य विद्यते ।", "न हि कल्याणकृत्कश्चिद्दुर्गतिं तात गच्छति ॥४०॥"], "iast": ["śrī-bhagavān uvāca", "pārtha naiveha nāmutra vināśas tasya vidyate", "na hi kalyāṇa-kṛt kaścid durgatiṃ tāta gacchati"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, ni en este mundo ni en el otro hay perdición para él; porque nadie que obra el bien, amigo mío, va a parar a un mal destino.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "en verdad"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí, en este mundo"}, {"iast": "amutra", "sa": "अमुत्र", "gram": "ind.", "es": "allá, en el otro mundo"}, {"iast": "vināśaḥ", "sa": "विनाशः", "gram": "nom. sg. m.", "es": "perdición", "analisis": "vi-√naś (perecer)"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. m. pron.", "es": "para él"}, {"iast": "vidyate", "sa": "विद्यते", "gram": "3 sg. pres. pas.", "es": "hay", "analisis": "√vid (hallarse, existir)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque"}, {"iast": "kalyāṇa-kṛt", "sa": "कल्याणकृत्", "gram": "nom. sg. m. comp.", "es": "que obra el bien", "analisis": "kalyāṇa (lo bueno, lo bienhechor) + kṛt (que hace; √kṛ)"}, {"iast": "kaścit", "sa": "कश्चित्", "gram": "nom. sg. m. pron.", "es": "alguno (con na: nadie)"}, {"iast": "durgatim", "sa": "दुर्गतिम्", "gram": "ac. sg. f.", "es": "un mal destino", "analisis": "dus (mal) + gati (camino, destino)"}, {"iast": "tāta", "sa": "तात", "gram": "voc. sg. m.", "es": "amigo mío", "analisis": "término de afecto: «padre», «hijo», «querido»"}, {"iast": "gacchati", "sa": "गच्छति", "gram": "3 sg. pres. act.", "es": "va", "analisis": "√gam (ir)"}], "nota": "<p><em>Tāta</em>: palabra de afecto, propiamente «padre» o «hijo», con la que se llama a alguien querido; es la única vez que Kṛṣṇa la usa en la Gītā. <em>Durgati</em>: «mal camino», «mal destino». La respuesta recoge las dos mitades de la pregunta: «ni en este mundo ni en el otro» responde al «caído de uno y otro lado» de <a class=\"vref\" href=\"capitulo-06.html#v38\" data-v=\"6.38\">6.38</a>.</p>", "interp": [{"titulo": "Una promesa", "html": "<p>Kṛṣṇa no responde con una teoría, sino con una promesa: el esfuerzo hecho en el camino no se pierde. Es la misma idea de <a class=\"vref\" href=\"capitulo-02.html#v40\" data-v=\"2.40\">2.40</a>, «en este camino no se pierde ningún intento», ahora desplegada a lo largo de varias vidas en los versos siguientes.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ningun-esfuerzo-se-pierde"}, {"n": 41, "hablante": "krsna", "sa": ["प्राप्य पुण्यकृतां लोकानुषित्वा शाश्वतीः समाः ।", "शुचीनां श्रीमतां गेहे योगभ्रष्टोऽभिजायते ॥४१॥"], "iast": ["prāpya puṇya-kṛtāṃ lokān uṣitvā śāśvatīḥ samāḥ", "śucīnāṃ śrīmatāṃ gehe yoga-bhraṣṭo 'bhijāyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Tras alcanzar los mundos de los que obraron el bien y morar en ellos incontables años, <a class=\"t\" href=\"glosario.html#yoga-bhrasta\" data-t=\"yoga-bhrasta\">el que se desvió del yoga</a> vuelve a nacer en la casa de gente pura y próspera.</span>", "palabras": [{"iast": "prāpya", "sa": "प्राप्य", "gram": "abs.", "es": "tras alcanzar", "analisis": "pra-√āp (alcanzar)"}, {"iast": "puṇya-kṛtām", "sa": "पुण्यकृताम्", "gram": "gen. pl. m. comp.", "es": "de los que obraron el bien", "analisis": "puṇya (mérito, obra buena) + kṛt (que hace)"}, {"iast": "lokān", "sa": "लोकान्", "gram": "ac. pl. m.", "es": "los mundos"}, {"iast": "uṣitvā", "sa": "उषित्वा", "gram": "abs.", "es": "tras morar", "analisis": "√vas (habitar)"}, {"iast": "śāśvatīḥ", "sa": "शाश्वतीः", "gram": "ac. pl. f.", "es": "incontables", "analisis": "śāśvata (perpetuo): aquí, «muchísimos»"}, {"iast": "samāḥ", "sa": "समाः", "gram": "ac. pl. f.", "es": "años", "analisis": "samā (año)"}, {"iast": "śucīnām", "sa": "शुचीनाम्", "gram": "gen. pl. m.", "es": "de los puros"}, {"iast": "śrīmatām", "sa": "श्रीमताम्", "gram": "gen. pl. m.", "es": "de los prósperos", "analisis": "śrī (prosperidad, fortuna) + -mat (dotado de)"}, {"iast": "gehe", "sa": "गेहे", "gram": "loc. sg. n.", "es": "en la casa"}, {"iast": "yoga-bhraṣṭaḥ", "sa": "योगभ्रष्टः", "gram": "nom. sg. m. comp.", "es": "el que se desvió del yoga", "ref": "yoga-bhrasta", "analisis": "yoga + bhraṣṭa (caído; √bhraṃś)"}, {"iast": "abhijāyate", "sa": "अभिजायते", "gram": "3 sg. pres. med.", "es": "nace", "analisis": "abhi-√jan (nacer)"}], "nota": "<p><em>Puṇya-kṛtām lokān</em>: «los mundos de los que obraron el bien», los cielos que se ganan con el mérito y de los que se vuelve cuando éste se agota (<a class=\"vref\" href=\"capitulo-09.html#v20\" data-v=\"9.20\">9.20</a>–<a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>). <em>Śāśvatīḥ samāḥ</em>: «años perpetuos», es decir, muchísimos; no eternos, porque después vuelve a nacer. <em>Śucīnāṃ śrīmatām</em>: «de los puros y prósperos».</p>", "interp": [{"titulo": "Dos renacimientos", "html": "<p>El texto ofrece dos destinos: renacer en una familia pura y próspera tras una larga estancia en los cielos, o nacer directamente en una familia de yoguis (<a class=\"vref\" href=\"capitulo-06.html#v42\" data-v=\"6.42\">6.42</a>). <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> los reparte según cuánto tiempo practicó el yogui antes de desviarse: el primero corresponde al que practicó poco; el segundo, al que practicó mucho. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> distingue de modo parecido al que se desvió al empezar el yoga del que lo tenía ya maduro; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, según le queden o no deseos de goce.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ningun-esfuerzo-se-pierde"}, {"n": 42, "hablante": "krsna", "sa": ["अथवा योगिनामेव कुले भवति धीमताम् ।", "एतद्धि दुर्लभतरं लोके जन्म यदीदृशम् ॥४२॥"], "iast": ["athavā yoginām eva kule bhavati dhīmatām", "etad dhi durlabhataraṃ loke janma yad īdṛśam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">O bien nace en una familia de <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yoguis</a> sabios; pero un nacimiento así es aún más difícil de alcanzar en este mundo.</span>", "palabras": [{"iast": "athavā", "sa": "अथवा", "gram": "ind.", "es": "o bien"}, {"iast": "yoginām", "sa": "योगिनाम्", "gram": "gen. pl. m.", "es": "de yoguis", "ref": "yogin"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "kule", "sa": "कुले", "gram": "loc. sg. n.", "es": "en la familia", "ref": "kula"}, {"iast": "bhavati", "sa": "भवति", "gram": "3 sg. pres. act.", "es": "nace, llega a ser", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "dhīmatām", "sa": "धीमताम्", "gram": "gen. pl. m.", "es": "sabios", "analisis": "dhī (inteligencia) + -mat (dotado de)"}, {"iast": "etat", "sa": "एतत्", "gram": "nom. sg. n. pron.", "es": "esto"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pero, en verdad"}, {"iast": "durlabhataram", "sa": "दुर्लभतरम्", "gram": "nom. sg. n. adj.", "es": "más difícil de alcanzar", "analisis": "dus (difícil) + labha (obtención; √labh) + -tara (comparativo)"}, {"iast": "loke", "sa": "लोके", "gram": "loc. sg. m.", "es": "en el mundo"}, {"iast": "janma", "sa": "जन्म", "gram": "nom. sg. n.", "es": "nacimiento", "analisis": "janman (nacimiento; √jan)"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. rel.", "es": "que"}, {"iast": "īdṛśam", "sa": "ईदृशम्", "gram": "nom. sg. n. adj.", "es": "semejante, así"}], "nota": "<p><em>Dhīmat</em>: «dotado de inteligencia», sabio. Un nacimiento así es «más difícil de obtener» que el del verso anterior, y más valioso: ofrece desde el principio las condiciones para retomar el yoga.</p>", "interp": [{"titulo": "Una familia pobre de yoguis", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> precisa que los yoguis de este verso son pobres, en contraste con la familia próspera del anterior: el nacimiento más difícil de obtener no es el más acomodado. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> explica por qué es más valioso: porque conduce a la liberación.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ningun-esfuerzo-se-pierde"}, {"n": 43, "hablante": "krsna", "sa": ["तत्र तं बुद्धिसंयोगं लभते पौर्वदेहिकम् ।", "यतते च ततो भूयः संसिद्धौ कुरुनन्दन ॥४३॥"], "iast": ["tatra taṃ buddhi-saṃyogaṃ labhate paurva-dehikam", "yatate ca tato bhūyaḥ saṃsiddhau kuru-nandana"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Allí recobra la disposición del <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> que tuvo en su vida anterior, y a partir de ella se esfuerza de nuevo, con más empeño, por alcanzar la perfección, oh <a class=\"t\" href=\"glosario.html#kurunandana\" data-t=\"kurunandana\">Kuru-nandana</a>.</span>", "palabras": [{"iast": "tatra", "sa": "तत्र", "gram": "ind.", "es": "allí"}, {"iast": "tam", "sa": "तम्", "gram": "ac. sg. m. pron.", "es": "esa"}, {"iast": "buddhi-saṃyogam", "sa": "बुद्धिसंयोगम्", "gram": "ac. sg. m. comp.", "es": "la unión con el entendimiento", "ref": "buddhi", "analisis": "buddhi (entendimiento) + saṃyoga (unión, contacto)"}, {"iast": "labhate", "sa": "लभते", "gram": "3 sg. pres. med.", "es": "recobra, obtiene", "analisis": "√labh (obtener)"}, {"iast": "paurva-dehikam", "sa": "पौर्वदेहिकम्", "gram": "ac. sg. m. adj.", "es": "de su cuerpo anterior", "analisis": "pūrva (anterior) + deha (cuerpo) + -ika: «propio del cuerpo anterior»"}, {"iast": "yatate", "sa": "यतते", "gram": "3 sg. pres. med.", "es": "se esfuerza", "analisis": "√yat (esforzarse)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "tataḥ", "sa": "ततः", "gram": "ind.", "es": "a partir de ahí"}, {"iast": "bhūyaḥ", "sa": "भूयः", "gram": "ind.", "es": "de nuevo, con más empeño"}, {"iast": "saṃsiddhau", "sa": "संसिद्धौ", "gram": "loc. sg. f.", "es": "hacia la perfección", "analisis": "saṃsiddhi (perfección)"}, {"iast": "kuru-nandana", "sa": "कुरुनन्दन", "gram": "voc. sg. m. comp.", "es": "oh Kuru-nandana", "ref": "kurunandana"}], "nota": "<p><em>Buddhi-saṃyoga</em>: «la unión con el entendimiento», es decir, la disposición del entendimiento que había alcanzado. <em>Paurva-dehika</em>: «propio del cuerpo anterior», de la vida anterior. <em>Bhūyaḥ</em>: «más, de nuevo».</p>", "interp": [{"titulo": "Lo que pasa de una vida a otra", "html": "<p>El verso precisa qué se conserva de una vida a otra: no los recuerdos, sino la disposición del entendimiento que se había alcanzado. Por eso el que vuelve a nacer no empieza de cero, y el verso siguiente añade que la práctica anterior lo arrastra aun sin quererlo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ningun-esfuerzo-se-pierde"}, {"n": 44, "hablante": "krsna", "sa": ["पूर्वाभ्यासेन तेनैव ह्रियते ह्यवशोऽपि सः ।", "जिज्ञासुरपि योगस्य शब्दब्रह्मातिवर्तते ॥४४॥"], "iast": ["pūrvābhyāsena tenaiva hriyate hy avaśo 'pi saḥ", "jijñāsur api yogasya śabda-brahmātivartate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Por esa misma <a class=\"t\" href=\"glosario.html#abhyasa\" data-t=\"abhyasa\">práctica</a> anterior es arrastrado, aun sin quererlo. Incluso el que sólo desea conocer el yoga va más allá de la palabra del <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Veda</a>.</span>", "palabras": [{"iast": "pūrva-abhyāsena", "sa": "पूर्वाभ्यासेन", "gram": "instr. sg. m. comp.", "es": "por la práctica anterior", "ref": "abhyasa", "analisis": "pūrva (anterior) + abhyāsa (práctica repetida)"}, {"iast": "tena", "sa": "तेन", "gram": "instr. sg. m. pron.", "es": "por esa"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "misma"}, {"iast": "hriyate", "sa": "ह्रियते", "gram": "3 sg. pres. pas.", "es": "es arrastrado", "analisis": "√hṛ (llevar, arrastrar)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "en verdad"}, {"iast": "avaśaḥ", "sa": "अवशः", "gram": "nom. sg. m. adj.", "es": "sin quererlo", "analisis": "a (no) + vaśa (voluntad): «a su pesar»"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}, {"iast": "jijñāsuḥ", "sa": "जिज्ञासुः", "gram": "nom. sg. m. adj.", "es": "el que desea conocer", "analisis": "desiderativo de √jñā (conocer)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "incluso"}, {"iast": "yogasya", "sa": "योगस्य", "gram": "gen. sg. m.", "es": "el yoga", "ref": "yoga"}, {"iast": "śabda-brahma", "sa": "शब्दब्रह्म", "gram": "ac. sg. n. comp.", "es": "el brahman de la palabra, el Veda", "ref": "veda", "analisis": "śabda (palabra, sonido) + brahman"}, {"iast": "ativartate", "sa": "अतिवर्तते", "gram": "3 sg. pres. med.", "es": "va más allá", "analisis": "ati-√vṛt (pasar más allá)"}], "nota": "<p><em>Hriyate hy avaśo &#x27;pi</em>: «es arrastrado aun sin quererlo»: la práctica anterior obra como una corriente. <em>Śabda-brahman</em>, literalmente «el brahman de la palabra», es el Veda para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende en cambio la naturaleza material (<em>prakṛti</em>), lo que puede nombrarse con palabras como «dios», «hombre» o «cielo», y que el yogui deja atrás al alcanzar el sí-mismo. «Ir más allá» de él es dejar atrás los ritos y sus frutos, como pedía Kṛṣṇa en <a class=\"vref\" href=\"capitulo-02.html#v45\" data-v=\"2.45\">2.45</a>–<a class=\"vref\" href=\"capitulo-02.html#v46\" data-v=\"2.46\">2.46</a> y <a class=\"vref\" href=\"capitulo-02.html#v52\" data-v=\"2.52\">2.52</a>–<a class=\"vref\" href=\"capitulo-02.html#v53\" data-v=\"2.53\">2.53</a>.</p>", "interp": [{"titulo": "Más allá de los ritos", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende que el que sólo desea conocer el yoga, aunque se haya desviado de él, ya va más allá del fruto de los ritos que prescribe el Veda; cuánto más el que lo conoce y lo practica.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ningun-esfuerzo-se-pierde"}, {"n": 45, "hablante": "krsna", "sa": ["प्रयत्नाद्यतमानस्तु योगी संशुद्धकिल्बिषः ।", "अनेकजन्मसंसिद्धस्ततो याति परां गतिम् ॥४५॥"], "iast": ["prayatnād yatamānas tu yogī saṃśuddha-kilbiṣaḥ", "aneka-janma-saṃsiddhas tato yāti parāṃ gatim"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero el yogui que se esfuerza con empeño, limpio de faltas y perfeccionado a lo largo de muchos nacimientos, alcanza entonces la meta suprema.</span>", "palabras": [{"iast": "prayatnāt", "sa": "प्रयत्नात्", "gram": "abl. sg. m.", "es": "con empeño", "analisis": "pra-√yat (esforzarse)"}, {"iast": "yatamānaḥ", "sa": "यतमानः", "gram": "nom. sg. m. part. pres.", "es": "que se esfuerza", "analisis": "√yat (esforzarse)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "el yogui", "ref": "yogin"}, {"iast": "saṃśuddha-kilbiṣaḥ", "sa": "संशुद्धकिल्बिषः", "gram": "nom. sg. m. comp.", "es": "limpio de faltas", "analisis": "saṃśuddha (purificado; sam-√śudh) + kilbiṣa (falta, mancha)"}, {"iast": "aneka-janma-saṃsiddhaḥ", "sa": "अनेकजन्मसंसिद्धः", "gram": "nom. sg. m. comp.", "es": "perfeccionado a lo largo de muchos nacimientos", "analisis": "aneka (muchos) + janman (nacimiento) + saṃsiddha (perfeccionado)"}, {"iast": "tataḥ", "sa": "ततः", "gram": "ind.", "es": "entonces"}, {"iast": "yāti", "sa": "याति", "gram": "3 sg. pres. act.", "es": "alcanza, va", "analisis": "√yā (ir)"}, {"iast": "parām", "sa": "पराम्", "gram": "ac. sg. f. adj.", "es": "suprema"}, {"iast": "gatim", "sa": "गतिम्", "gram": "ac. sg. f.", "es": "meta"}], "nota": "<p><em>Prayatnād yatamānaḥ</em>: «esforzándose con empeño», en contraste con el <em>ayati</em> de <a class=\"vref\" href=\"capitulo-06.html#v37\" data-v=\"6.37\">6.37</a>, el que no persevera. <em>Aneka-janma-saṃsiddha</em>: «llevado a la perfección a lo largo de muchos nacimientos»; compárese <a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a>, «al cabo de muchos nacimientos». <em>Kilbiṣa</em>: «falta, mancha», como en <a class=\"vref\" href=\"capitulo-04.html#v21\" data-v=\"4.21\">4.21</a>.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ningun-esfuerzo-se-pierde"}, {"n": 46, "hablante": "krsna", "sa": ["तपस्विभ्योऽधिको योगी ज्ञानिभ्योऽपि मतोऽधिकः ।", "कर्मिभ्यश्चाधिको योगी तस्माद्योगी भवार्जुन ॥४६॥"], "iast": ["tapasvibhyo 'dhiko yogī jñānibhyo 'pi mato 'dhikaḥ", "karmibhyaś cādhiko yogī tasmād yogī bhavārjuna"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> es superior a los <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">ascetas</a>; se le tiene también por superior a los <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">sabios</a>, y es superior a los hombres de <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>. Por eso, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>, sé yogui.</span>", "palabras": [{"iast": "tapasvibhyaḥ", "sa": "तपस्विभ्यः", "gram": "abl. pl. m.", "es": "que los ascetas", "ref": "tapas", "analisis": "tapasvin (el que practica la austeridad)"}, {"iast": "adhikaḥ", "sa": "अधिकः", "gram": "nom. sg. m. adj.", "es": "superior"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "el yogui", "ref": "yogin"}, {"iast": "jñānibhyaḥ", "sa": "ज्ञानिभ्यः", "gram": "abl. pl. m.", "es": "que los sabios", "ref": "jnana", "analisis": "jñānin (el que tiene conocimiento)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "mataḥ", "sa": "मतः", "gram": "nom. sg. m. ppp", "es": "se le tiene por", "analisis": "√man (pensar, considerar)"}, {"iast": "adhikaḥ", "sa": "अधिकः", "gram": "nom. sg. m. adj.", "es": "superior"}, {"iast": "karmibhyaḥ", "sa": "कर्मिभ्यः", "gram": "abl. pl. m.", "es": "que los hombres de acción", "ref": "karma", "analisis": "karmin (el que actúa; el que cumple los ritos)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "adhikaḥ", "sa": "अधिकः", "gram": "nom. sg. m. adj.", "es": "superior"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "el yogui", "ref": "yogin"}, {"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. n. pron.", "es": "por eso"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "yogui", "ref": "yogin"}, {"iast": "bhava", "sa": "भव", "gram": "2 sg. impv. act.", "es": "sé", "analisis": "√bhū (ser)"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}], "nota": "<p><em>Tapasvin</em>: «asceta», el que practica la <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridad</a>; <em>jñānin</em>: «el que tiene conocimiento» (véanse las alternativas); <em>karmin</em>: «el que actúa», aquí el que se dedica a la acción ritual. <em>Mataḥ</em>: «se considera, se tiene por». La exhortación final, «sé yogui», resume el capítulo.</p>", "interp": [{"titulo": "Sé yogui", "html": "<p>Kṛṣṇa compara al yogui con tres figuras reconocidas de su tiempo —el asceta, el que tiene conocimiento y el que cumple los ritos— y lo pone por encima de las tres. No rechaza sus prácticas: el capítulo empezó definiendo al yogui como el que hace lo que debe hacer sin depender del fruto (<a class=\"vref\" href=\"capitulo-06.html#v1\" data-v=\"6.1\">6.1</a>), y lo ha descrito después como el que medita con la mente sujeta. Lo que lo distingue no es una actividad, sino la mente unida a lo supremo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "El yogui es superior a los ascetas; se le tiene también por superior a los eruditos, y es superior a los que se dedican a los ritos. Por eso, oh Arjuna, sé yogui.", "nota": "<p><em>Jñānin</em> puede ser el que ha realizado el conocimiento o el que sólo lo posee como saber. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo entiende aquí en el segundo sentido, la erudición en el sentido de las escrituras (<em>śāstrārtha-pāṇḍitya</em>), y entiende <em>karmin</em> como el que realiza ritos como el <em>agnihotra</em>; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> lee <em>jñānin</em> del mismo modo. No dan la razón, pero esa lectura evita poner al yogui por encima del que conoce, al que la Gītā pone por encima de los demás (<a class=\"vref\" href=\"capitulo-07.html#v17\" data-v=\"7.17\">7.17</a>–<a class=\"vref\" href=\"capitulo-07.html#v18\" data-v=\"7.18\">7.18</a>). <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> entiende <em>jñānin</em> como el que sólo tiene un conocimiento indirecto; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, como el que posee saberes distintos del conocimiento del sí-mismo; y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, como el que conoce el yoga, no brahman. La traducción principal deja los términos abiertos.</p>"}], "ens": "el-mas-unido-de-los-yoguis"}, {"n": 47, "hablante": "krsna", "sa": ["योगिनामपि सर्वेषां मद्गतेनान्तरात्मना ।", "श्रद्धावान्भजते यो मां स मे युक्ततमो मतः ॥४७॥"], "iast": ["yoginām api sarveṣāṃ mad-gatenāntarātmanā", "śraddhāvān bhajate yo māṃ sa me yuktatamo mataḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y de todos los yoguis, el que, lleno de <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a>, me <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">adora</a> con su ser interior puesto en mí, ése es para mí el más <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a>.</span>", "palabras": [{"iast": "yoginām", "sa": "योगिनाम्", "gram": "gen. pl. m.", "es": "de los yoguis", "ref": "yogin"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "y aun"}, {"iast": "sarveṣām", "sa": "सर्वेषाम्", "gram": "gen. pl. m. pron.", "es": "de todos"}, {"iast": "mad-gatena", "sa": "मद्गतेन", "gram": "instr. sg. m. comp.", "es": "puesto en mí", "analisis": "mad (en mí) + gata (ido; √gam)"}, {"iast": "antar-ātmanā", "sa": "अन्तरात्मना", "gram": "instr. sg. m. comp.", "es": "con su ser interior", "ref": "atman", "analisis": "antar (dentro) + ātman (sí-mismo)"}, {"iast": "śraddhāvān", "sa": "श्रद्धावान्", "gram": "nom. sg. m. adj.", "es": "lleno de fe", "ref": "sraddha", "analisis": "śraddhā (fe) + -vat (dotado de)"}, {"iast": "bhajate", "sa": "भजते", "gram": "3 sg. pres. med.", "es": "adora", "ref": "bhakti", "analisis": "√bhaj (participar, adherirse, adorar, servir), la raíz de bhakti"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "el que"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "me, a mí"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "para mí"}, {"iast": "yukta-tamaḥ", "sa": "युक्ततमः", "gram": "nom. sg. m. adj.", "es": "el más unido en yoga", "ref": "yukta", "analisis": "yukta (unido, disciplinado) + -tama (superlativo)"}, {"iast": "mataḥ", "sa": "मतः", "gram": "nom. sg. m. ppp", "es": "es considerado", "analisis": "√man (pensar, considerar)"}], "nota": "<p><em>Bhajate</em>, de √<em>bhaj</em>, la raíz de <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">bhakti</a>: «participa de, se adhiere a, adora, sirve». <em>Mad-gatena antarātmanā</em>: «con el ser interior ido a mí», puesto en mí. <em>Yuktatama</em>: superlativo de <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">yukta</a>, «el más unido» o «el más disciplinado». El verso cierra el primer tercio de la obra y pone la devoción en la cima de la jerarquía de los yoguis; el capítulo 7 empieza precisamente con el que tiene «la mente apegada a mí» (<a class=\"vref\" href=\"capitulo-07.html#v1\" data-v=\"7.1\">7.1</a>).</p>", "interp": [{"titulo": "El paso a la devoción", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> ve en este verso el paso a la <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoción</a>, tema de los capítulos siguientes: el mejor de los yoguis es el que, por su amor extremo al Señor, no soporta estar separado de él y lo adora con todo su ser.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "La bisagra de la obra", "html": "<p>La tradición de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, desde su predecesor Yāmuna (<em>Gītārtha-saṅgraha</em>), divide la Gītā en tres grupos de seis capítulos: los seis primeros enseñan el yoga de la acción y del conocimiento, que lleva a la visión del sí-mismo; los seis siguientes, la devoción, para la que esa visión prepara; los seis últimos completan y aclaran lo anterior. Este verso es la bisagra entre los dos primeros grupos.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "El más alto de los yoguis", "html": "<p>En la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, Prabhupāda ve en este verso la conclusión del capítulo y de todo el yoga: el más alto de los yoguis es el que practica el <em>bhakti-yoga</em>, el servicio amoroso a Kṛṣṇa, y en él culminan las demás formas de yoga.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Y de todos los yoguis, el que, lleno de fe, me ama y me sirve con su ser interior puesto en mí, ése es, a mi juicio, el mejor de los yoguis.", "nota": "<p><em>Bhajate</em> puede entenderse como «adora», como en la traducción principal, o, más cerca de la raíz <em>bhaj</em>, «participa de», «ama», «sirve»; así lo vierten las traducciones devocionales, como la de Prabhupāda («renders transcendental loving service to Me»), que rechaza expresamente traducir <em>bhaj</em> por «adorar» (<em>worship</em>), porque para él ese verbo designa el servicio con amor que sólo se debe al Señor supremo. <em>Yuktatamaḥ</em> es literalmente «el más unido»; la alternativa lo entiende como «el mejor de los yoguis», y <em>me mataḥ</em>, «considerado por mí», como «a mi juicio».</p>"}], "ens": "el-mas-unido-de-los-yoguis"}], "ensenanzas": [{"id": "renunciar-a-la-intencion", "desde": 1, "hasta": 2, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "La renuncia es renunciar a la intención", "resumen": "<p>Renunciante y yogui no es el que abandona los fuegos y los ritos, sino el que hace lo que debe hacerse sin depender del fruto. Renuncia y yoga son lo mismo, porque las dos exigen dejar la intención (<em>saṅkalpa</em>): la imagen de lo deseado que pone en marcha la acción interesada. La renuncia pasa de la forma de vida a la actitud interior, como ya anunciaba <a class=\"vref\" href=\"capitulo-05.html#v3\" data-v=\"5.3\">5.3</a>.</p>"}, {"id": "ascender-al-yoga", "desde": 3, "hasta": 4, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Ascender al yoga: la acción para subir, la calma arriba", "resumen": "<p>El camino tiene dos tramos. Para el que quiere ascender al yoga, el medio es la acción hecha sin apego; para el que ya ha ascendido, la calma (<em>śama</em>). Se ha ascendido cuando ya no hay apego a los objetos de los sentidos ni a las acciones, y se ha dejado toda intención. Si esa calma es el cese de la acción o la serenidad con que se sigue actuando es cuestión disputada (véanse las alternativas de <a class=\"vref\" href=\"capitulo-06.html#v3\" data-v=\"6.3\">6.3</a>).</p>"}, {"id": "elevarse-a-si-mismo", "desde": 5, "hasta": 6, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Elevarse a uno mismo por uno mismo", "resumen": "<p>Nadie puede subir por otro: uno ha de elevarse por sí mismo y no dejarse hundir. Uno mismo es su propio amigo cuando se ha vencido, y su propio enemigo cuando no es dueño de sí. El dominio de sí no es una lucha contra un enemigo exterior, sino la conversión del propio ánimo de adversario en aliado.</p>"}, {"id": "el-que-se-ha-vencido", "desde": 7, "hasta": 9, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El que se ha vencido: la misma mirada para todo", "resumen": "<p>El que se ha vencido permanece recogido en el frío y el calor, el placer y el dolor, la honra y la deshonra. Saciado de conocimiento y de su realización, inmutable, ve iguales el terrón, la piedra y el oro; y mira con el mismo entendimiento al amigo y al enemigo, al pariente y al extraño, al bueno y al malvado. Ése, dice Kṛṣṇa, sobresale.</p>"}, {"id": "sentarse-a-meditar", "desde": 10, "hasta": 15, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Cómo sentarse a meditar", "resumen": "<p>La técnica que <a class=\"vref\" href=\"capitulo-05.html#v27\" data-v=\"5.27\">5.27</a>–<a class=\"vref\" href=\"capitulo-05.html#v28\" data-v=\"5.28\">5.28</a> esbozó, ahora paso a paso. Retirarse a un lugar apartado y limpio, solo, sin esperar nada ni poseer nada. Disponer un <a class=\"t\" href=\"glosario.html#asana\" data-t=\"asana\">asiento</a> firme, ni alto ni bajo, de hierba <a class=\"t\" href=\"glosario.html#kusa\" data-t=\"kusa\">kuśa</a>, piel y tela. Sentarse con el cuerpo, la cabeza y el cuello alineados e inmóviles, la mirada recogida hacia la punta de la nariz, sin mirar alrededor. Concentrar la mente en un solo punto, dominando el pensamiento y los sentidos; sereno, sin miedo, en <a class=\"t\" href=\"glosario.html#brahmacarya\" data-t=\"brahmacarya\">castidad</a>, con el pensamiento en Kṛṣṇa. El fruto es la <a class=\"t\" href=\"glosario.html#santi\" data-t=\"santi\">paz</a> que culmina en el <a class=\"t\" href=\"glosario.html#nirvana\" data-t=\"nirvana\">nirvāṇa</a>.</p>"}, {"id": "la-medida-justa", "desde": 16, "hasta": 17, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Ni demasiado ni demasiado poco", "resumen": "<p>El <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> no es para el que come o duerme en exceso, ni para el que ayuna o vela en exceso. Quien es moderado en la comida y el esparcimiento, en el esfuerzo de sus acciones, en el sueño y en la vigilia, encuentra en el yoga el fin del <a class=\"t\" href=\"glosario.html#duhkha\" data-t=\"duhkha\">sufrimiento</a>: la medida en la vida diaria es parte de la práctica.</p>"}, {"id": "la-lampara-sin-viento", "desde": 18, "hasta": 19, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "La lámpara sin viento", "resumen": "<p>La meta de la meditación tiene un criterio y una imagen. El criterio: el <a class=\"t\" href=\"glosario.html#citta\" data-t=\"citta\">pensamiento</a> bien dominado reposa sólo en el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>, sin anhelo de ningún <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a>; entonces se está <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a>. La imagen: una lámpara al abrigo del viento, cuya llama no vacila. El pensamiento recogido no se apaga ni se duerme: sigue encendido, pero quieto.</p>"}, {"id": "la-desunion-del-dolor", "desde": 20, "hasta": 23, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El yoga, desunión de la unión con el dolor", "resumen": "<p>Kṛṣṇa describe el estado al que lleva la práctica: el <a class=\"t\" href=\"glosario.html#citta\" data-t=\"citta\">pensamiento</a> refrenado se aquieta; uno ve el sí-mismo por el sí-mismo y se complace en él; conoce una <a class=\"t\" href=\"glosario.html#sukha\" data-t=\"sukha\">dicha</a> infinita, más allá de los sentidos, tras la cual ninguna otra ganancia parece mayor y en la que ni el <a class=\"t\" href=\"glosario.html#duhkha\" data-t=\"duhkha\">dolor</a> más grave conmueve. Eso se llama <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>: la desunión de la unión con el dolor. Y como es la meta, ha de practicarse con determinación y sin desánimo.</p>"}, {"id": "traer-la-mente-de-vuelta", "desde": 24, "hasta": 26, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Traer la mente de vuelta, poco a poco", "resumen": "<p>La técnica en cuatro pasos: abandonar por completo los <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseos</a> que nacen de la <a class=\"t\" href=\"glosario.html#sankalpa\" data-t=\"sankalpa\">intención</a>; recoger con la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> el conjunto de los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a>; aquietarse poco a poco, con el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> sostenido por la firmeza, hasta que la mente, asentada en el sí-mismo, no piense en nada más; y cada vez que la mente, inquieta e inestable, se escape, adondequiera que vaya, refrenarla desde allí y devolverla al dominio del sí-mismo. La distracción no es el fracaso de la práctica: es el momento de practicar.</p>"}, {"id": "el-contacto-con-brahman", "desde": 27, "hasta": 28, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "La dicha del contacto con brahman", "resumen": "<p>Al <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> de mente serena, con el <a class=\"t\" href=\"glosario.html#rajas\" data-t=\"rajas\">rajas</a> calmado y libre de impurezas, le llega la <a class=\"t\" href=\"glosario.html#sukha\" data-t=\"sukha\">dicha</a> suprema: la del <a class=\"t\" href=\"glosario.html#sparsa\" data-t=\"sparsa\">contacto</a> con <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, que no tiene término. Es la respuesta a <a class=\"vref\" href=\"capitulo-05.html#v22\" data-v=\"5.22\">5.22</a>: los goces del contacto con los objetos se agotan; el contacto con brahman, no.</p>"}, {"id": "el-si-mismo-en-todos-los-seres", "desde": 29, "hasta": 32, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El sí-mismo en todos los seres y todos en mí", "resumen": "<p>La culminación de la meditación es una manera de ver. El yogui ve el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a> en todos los seres y a todos los seres en el sí-mismo (<a class=\"vref\" href=\"capitulo-06.html#v29\" data-v=\"6.29\">6.29</a>); ve a Kṛṣṇa en todo y todo en Kṛṣṇa, y entonces ya no se pierden de vista el uno al otro (<a class=\"vref\" href=\"capitulo-06.html#v30\" data-v=\"6.30\">6.30</a>); lo adora como presente en todos, y vive en él cualquiera que sea su condición (<a class=\"vref\" href=\"capitulo-06.html#v31\" data-v=\"6.31\">6.31</a>); y, tomándose a sí mismo como medida, ve igual en todos el placer y el dolor (<a class=\"vref\" href=\"capitulo-06.html#v32\" data-v=\"6.32\">6.32</a>). La meditación termina en la mirada igual y en la compasión.</p>"}, {"id": "practica-y-desapego", "desde": 35, "hasta": 36, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Práctica y desapego: cómo se sujeta la mente", "resumen": "<p>Arjuna objeta que la mente es inquieta como el viento (<a class=\"vref\" href=\"capitulo-06.html#v33\" data-v=\"6.33\">6.33</a>–<a class=\"vref\" href=\"capitulo-06.html#v34\" data-v=\"6.34\">6.34</a>). Kṛṣṇa lo concede y da el método: la mente se sujeta con dos medios a la vez, la <a class=\"t\" href=\"glosario.html#abhyasa\" data-t=\"abhyasa\">práctica</a>, volver una y otra vez al objeto de la meditación, y el <a class=\"t\" href=\"glosario.html#vairagya\" data-t=\"vairagya\">desapego</a>, dejar de desear lo que la arrastra fuera (<a class=\"vref\" href=\"capitulo-06.html#v35\" data-v=\"6.35\">6.35</a>). Para quien no se domina el yoga es difícil; para quien persevera con esos medios, posible (<a class=\"vref\" href=\"capitulo-06.html#v36\" data-v=\"6.36\">6.36</a>).</p>"}, {"id": "ningun-esfuerzo-se-pierde", "desde": 40, "hasta": 45, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Ningún esfuerzo se pierde", "resumen": "<p>El que avanza por el camino del yoga y no llega a la meta no se pierde: tras una estancia en los mundos de los que obraron bien, renace en condiciones propicias, recobra la disposición alcanzada y, arrastrado por su práctica anterior, sigue adelante hasta alcanzar, al cabo de muchos nacimientos, la meta suprema. Es el desarrollo de <a class=\"vref\" href=\"capitulo-02.html#v40\" data-v=\"2.40\">2.40</a>: en este camino no se pierde ningún intento.</p>"}, {"id": "el-mas-unido-de-los-yoguis", "desde": 46, "hasta": 47, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El yogui, y el más unido de los yoguis", "resumen": "<p>El yogui es superior al asceta, al que tiene conocimiento y al que cumple los ritos; y entre todos los yoguis, el más unido es el que adora a Kṛṣṇa con <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a>, con su ser interior puesto en él. El capítulo de la meditación termina en la <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoción</a>.</p>"}]};
